def _inc(key): _metrics[key] = _metrics.get(key, 0) + 1

def get_uptime() -> str:
    s = int(time_module.time() - _metrics["start_time"])
    d, s = divmod(s, 86400); h, s = divmod(s, 3600); m, s = divmod(s, 60)
    if d: return f"{d}d {h}h {m}m"
    if h: return f"{h}h {m}m {s}s"
    return f"{m}m {s}s"

