def require_api_key(x_api_key: Optional[str] = None,
                    authorization: Optional[str] = None):
    """
    API key authentication with canary token detection.
    Checks canaries FIRST — before normal auth validation.
    Canary use = confirmed attacker → log and reject.

    Accepts:
      1. Production key  — VERISIGIL_API_KEY env var
      2. Sandbox keys    — SANDBOX_API_KEY, VERISIGIL_SANDBOX_KEY env vars
      3. CLARA program   — vs-sandbox-demo-2026b (permanent sandbox key)
    Accepts X-API-Key header OR Authorization: Bearer token.
    """
    import re as _re
    import os as _os

    def _normalize(s):
        if not s:
            return ""
        return _re.sub(r"[^a-zA-Z0-9\-]", "", s.strip())

    received = _normalize(x_api_key or "")
    bearer   = ""
    if authorization:
        bearer = _normalize(authorization.replace("Bearer", "").strip())

    # Check canaries first
    if received and _check_canary(received):
        raise HTTPException(status_code=401, detail="Invalid or missing API key.")
    if bearer and _check_canary(bearer):
        raise HTTPException(status_code=401, detail="Invalid or missing API key.")

    # Valid keys — production + all sandbox variants
    valid_keys = set(filter(None, [
        _normalize(_os.environ.get("VERISIGIL_API_KEY", "") or ""),
        _normalize(API_KEY or ""),
        _normalize(_os.environ.get("SANDBOX_API_KEY", "") or ""),
        _normalize(_os.environ.get("VERISIGIL_SANDBOX_KEY", "") or ""),
        "vs-sandbox-demo-2026b",   # CLARA program sandbox key — permanent
        "vs-sandbox-demo-2026",    # Legacy sandbox key
    ]))

    key_to_check = received or bearer
    if not key_to_check or key_to_check not in valid_keys:
        raise HTTPException(
            status_code=401,
            detail="Invalid or missing API key. Include x-api-key header."
        )


def get_org_id_from_token(authorization: Optional[str] = None, x_api_key: Optional[str] = None) -> str:
    """
    Extract org_id for multi-tenant isolation.
    JWT: decode sub-claim (Supabase user_id maps to org)
    API key: returns 'sandbox' org scope
    Production: replace with full Supabase JWT JWKS verification
    """
    if authorization and authorization.startswith("Bearer "):
        token = authorization[7:]
        try:
            import jwt as _jwt
            # P0 FIX: Never decode without signature verification for authorization.
            # Architecture lock v1.0: unverified JWT claims must not be used for tenant isolation.
            # Production path: verify JWT signature against Supabase JWKS before using claims.
            # GET {SUPABASE_URL}/auth/v1/.well-known/jwks.json
            # For now: decode with verification=False is ONLY for non-consequential org_id
            # lookup in sandbox/dev; this must be replaced with JWKS verification in production.
            # PRODUCTION_GATE: this path must NOT be used for authorization or tenant isolation.
            decoded = _jwt.decode(token, options={"verify_signature": False})
            # Note: org_id derived from unverified token is used only for routing/sandbox.
            # Any consequential authorization check must go through VCB, not this function.
            return decoded.get("org_id") or decoded.get("sub", "jwt-org")
        except Exception:
            pass
    return "sandbox"

# ============================================================
# DB HELPERS
# ============================================================
def get_headers(write=False):
    key = SUPABASE_SERVICE_KEY if write else SUPABASE_KEY
    return {
        "apikey":        key,
        "Authorization": f"Bearer {key}",
        "Content-Type":  "application/json",
        "Prefer":        "return=representation",
    }

async def db_get(table, field, value):
    async with httpx.AsyncClient() as c:
        r = await c.get(
            f"{SUPABASE_URL}/rest/v1/{table}?{field}=eq.{value}",
            headers=get_headers(write=False), timeout=10
        )
        result = r.json()
        return result[0] if isinstance(result, list) and result else None

async def db_get_many(table, field, value, order_by=None, limit=None):
    url = f"{SUPABASE_URL}/rest/v1/{table}?{field}=eq.{value}"
    if order_by:
        url += f"&order={order_by}"
    if limit:
        url += f"&limit={limit}"
    async with httpx.AsyncClient() as c:
        r = await c.get(url, headers=get_headers(write=False), timeout=10)
        result = r.json()
        return result if isinstance(result, list) else []

async def db_patch(table, field, value, data):
    async with httpx.AsyncClient() as c:
        r = await c.patch(
            f"{SUPABASE_URL}/rest/v1/{table}?{field}=eq.{value}",
            headers=get_headers(write=True), json=data, timeout=10
        )
        if r.status_code >= 400:
            print(f"[DB PATCH ERROR] table={table} status={r.status_code} response={r.text[:200]}")
        result = r.json()
        return result[0] if isinstance(result, list) and result else data

# ============================================================
# CRYPTO
# ============================================================
# VCB CANONICAL FORM v2 — RFC 8785 JSON Canonicalization Scheme (JCS)
# STARTUP CHECK: rfc8785 must be installed or offline verification will fail silently
try:
    import rfc8785 as _rfc8785_check
    _RFC8785_AVAILABLE = True
except ImportError:
    _RFC8785_AVAILABLE = False
    import warnings
    warnings.warn(
        "CRITICAL: rfc8785 library not installed. "
        "VCB canonical form will fall back to compact JSON. "
        "Offline verification may fail for passports issued on this instance. "
        "Install: pip install rfc8785>=0.1.0",
        RuntimeWarning, stacklevel=2
    )
# Expert direction + 6-AI consensus: adopt a published standard, not a private profile.
# rfc8785 library (Trail of Bits): pip install rfc8785
# RFC 8785 handles: numeric precision, NaN/Infinity rejection, UTF-16 key sorting,
# surrogate rejection, I-JSON compliance — all Perplexity fact-check findings addressed.
# For ASCII-only keys (all VCB fields): identical to compact sort_keys=True.
# For float values: RFC 8785 converts 1000.0 → 1000 (our old form kept 1000.0).
_VCB_CANONICAL_SEPARATORS = (",", ":")  # kept for legacy reference only

def _vcb_canonical(obj) -> bytes:
    """
    RFC 8785 / JCS canonical serialization for ALL VCB operations.
    Used by both sign_payload (signing) and _vcc_hash (integrity).

    Properties guaranteed by RFC 8785:
    - Deterministic property ordering (UTF-16 code unit sort)
    - Numeric precision (1000.0 → b"1000", not b"1000.0")
    - NaN/Infinity: raises FloatDomainError (RFC 8259 §6 compliant)
    - Lone surrogates: rejected
    - No default=str coercion — type errors surface immediately
    - Returns UTF-8 bytes

    Replaces private "compact-json-sha256-v1" profile per expert direction §1/Phase 1.
    6/6 AI reviews confirmed need for published standard with test vectors.
    """
    try:
        import rfc8785 as _jcs
        return _jcs.dumps(obj)
    except ImportError:
        # Fallback if rfc8785 not installed — use strict compact form
        # This should never happen in production; add to requirements.txt
        import math
        def _check(o):
            if isinstance(o, float) and (math.isnan(o) or math.isinf(o)):
                raise ValueError(f"NaN/Infinity not permitted: {o}")
            if isinstance(o, dict):
                return {k: _check(v) for k, v in o.items()}
            if isinstance(o, (list, tuple)):
                return [_check(v) for v in o]
            return o
        return json.dumps(
            _check(obj), sort_keys=True, separators=_VCB_CANONICAL_SEPARATORS,
            ensure_ascii=False
        ).encode("utf-8")


def sign_payload(data: dict) -> str:
    """Sign using unified VCB canonical form — matches _vcc_hash exactly."""
    msg = _vcb_canonical(data)
    return base64.b64encode(SIGNING_KEY.sign(msg).signature).decode()

def verify_payload(data: dict, sig_b64: str) -> bool:
    """Verify using unified VCB canonical form — matches sign_payload exactly."""
    try:
        msg = _vcb_canonical(data)
        VERIFY_KEY.verify(msg, base64.b64decode(sig_b64))
        return True
    except Exception:
        return False

async def get_verifier(api_key: str) -> dict:
    if not api_key or api_key == "demo":
        return {"id": "ver_public", "name": "Public", "type": "public", "reputation": 0.3}
    verifier = await db_get("verifiers", "api_key", api_key)
    return verifier

async def update_verifier_reputation(verifier_id: str, action: str = "verify"):
    verifier = await db_get("verifiers", "id", verifier_id)
    if not verifier:
        return
    rep   = verifier.get("reputation", 0.5)
    rep  += 0.01 if action == "verify" else -0.05
    rep   = max(0.1, min(1.0, round(rep, 4)))
    count = (verifier.get("verifications") or 0) + 1
    await db_patch("verifiers", "id", verifier_id, {"reputation": rep, "verifications": count})

# ============================================================
# TRUST SCORE
# ============================================================
def calculate_trust_score(issued_at: str, verification_count: int,
                           high_threats: int, medium_threats: int,
                           unique_verifiers: int = 0,
                           avg_verifier_reputation: float = 0.5) -> float:
    try:
        days = max(0, (datetime.utcnow() - datetime.fromisoformat(issued_at)).days)
    except Exception:
        days = 0
    score  = 0.97
    score -= 0.001 * days
    score -= 0.15  * (high_threats or 0)
    score -= 0.05  * (medium_threats or 0)
    effective = max(unique_verifiers or 0, verification_count or 0)
    rep       = float(avg_verifier_reputation or 0.5)
    boost     = rep * 0.005 * math.log(effective + 1)
    score    += min(boost, 0.02)
    return max(0.0, min(1.0, round(score, 4)))

def trust_level(score: float) -> str:
    if score >= 0.80: return "TRUSTED"
    if score >= 0.60: return "FLAGGED"
    return "BLOCKED"

