@app.get("/v1/proof/estate", tags=["Proof Estate"])
async def proof_estate():
    """
    VeriSigil Proof Estate — ten independently testable proof
    artifacts covering every core governance claim.

    No authentication required. Run these proofs against the
    live API with the public sandbox key. No trust in VeriSigil
    required to verify any proof.

    Expert: "Each proof is tiny, deterministic, replayable,
    and independently testable. That is the level of engineering
    maturity enterprise buyers trust."

    VP-001: Delegation Passport Expiry
    VP-002: Credential Exfiltration Block
    VP-003: Boundary Registration Enforcement
    VP-004: Inter-AI Trust Negotiation Halt
    VP-005: Voice Script Violation Detection
    VP-006: AO Replay Prevention (independently verified)
    VP-007: HIGH Consequence Human Escalation (independently verified)
    VP-008: State Freshness Verification (independently verified)
    VP-009: AI Immune System Quarantine
    VP-010: Article 50 Disclosure Gate
    """
    return {
        **PROOF_ESTATE,
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }


@app.get("/v1/proof/estate/{proof_id}", tags=["Proof Estate"])
async def proof_estate_single(proof_id: str):
    """
    Retrieve a single proof artifact by ID (e.g. VP-001).
    No authentication required.
    """
    proof_id = proof_id.upper()
    proof = PROOF_ESTATE["proofs"].get(proof_id)
    if not proof:
        raise HTTPException(
            status_code=404,
            detail=f"Proof {proof_id} not found. Available: {list(PROOF_ESTATE['proofs'].keys())}"
        )
    return {
        **proof,
        "sandbox_key":  PROOF_ESTATE["sandbox_key"],
        "base_url":     PROOF_ESTATE["base_url"],
        "public_key":   PROOF_ESTATE["public_key"],
        "timestamp":    datetime.now(timezone.utc).isoformat(),
    }



# ============================================================
# SECRETS GOVERNANCE LAYER
# Expert: "Credential Governance exists. But enterprises also
# worry about API keys, tokens, service accounts, LLM
# credentials, OAuth refresh tokens, temporary credentials.
# A dedicated Secrets Governance Layer would be valuable."
#
# VeriSigil does not store secrets. It governs the lifecycle
# of secrets — creation, rotation, access, and expiry —
# before an AI agent can touch them.
# ============================================================

_SECRETS_REGISTRY: dict = {}  # secret_id -> governance record
_SECRETS_ACCESS_LOG: list = []


@app.post("/v1/secrets/register", tags=["Secrets Governance Layer"])
async def secrets_register(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    Secrets Governance — register a secret for AI governance.

    VeriSigil does NOT store the secret value. It governs:
    - Which AI agents are permitted to access it
    - Under what consequence tier access is allowed
    - When it expires and must be rotated
    - Who approved it and why
    - Every access attempt with a sealed receipt

    Secret types: API_KEY, TOKEN, SERVICE_ACCOUNT,
    LLM_CREDENTIAL, OAUTH_REFRESH, TEMPORARY_CREDENTIAL,
    CERTIFICATE, DATABASE_PASSWORD
    """
    require_api_key(x_api_key, authorization)
    ts        = datetime.now(timezone.utc).isoformat()
    secret_id = f"SEC-{hashlib.sha256(ts.encode()).hexdigest()[:12].upper()}"

    secret_type     = req.get("secret_type","")
    name            = req.get("name","")
    permitted_agents= req.get("permitted_agents",[])
    max_consequence = req.get("max_consequence","OPERATIONAL")
    approved_by     = req.get("approved_by","")
    expires_at      = req.get("expires_at","")
    rotation_days   = req.get("rotation_required_days", 90)
    purpose         = req.get("purpose","")

    if not approved_by:
        raise HTTPException(
            status_code=400,
            detail="approved_by required — all secrets require human approval before AI access"
        )

    record = {
        "schema":           "VGS-SECRETS-v1",
        "secret_id":        secret_id,
        "secret_type":      secret_type,
        "name":             name,
        "purpose":          purpose,
        "permitted_agents": permitted_agents,
        "max_consequence":  max_consequence,
        "approved_by":      approved_by,
        "expires_at":       expires_at,
        "rotation_required_days": rotation_days,
        "access_count":     0,
        "last_accessed":    None,
        "revoked":          False,
        "registered_at":    ts,
        "note":             "VeriSigil does not store the secret value. It governs access to it.",
    }

    seal = {
        "secret_id":  secret_id,
        "type":       secret_type,
        "approved_by":approved_by,
        "timestamp":  ts,
    }
    record["governance_signature"] = sign_governance_payload(seal)
    _SECRETS_REGISTRY[secret_id]  = record

    return {
        **record,
        "enforcement": (
            f"Only agents in permitted_agents list may access this secret. "
            f"Each access attempt must present this secret_id to POST /v1/secrets/access-check. "
            f"Access above {max_consequence} tier is automatically denied."
        ),
    }


@app.post("/v1/secrets/access-check", tags=["Secrets Governance Layer"])
async def secrets_access_check(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    Check whether an AI agent is permitted to access a secret.
    Called before the agent retrieves any credential or token.

    Returns ALLOW or DENY with a sealed receipt.
    Every access attempt is logged permanently.
    """
    require_api_key(x_api_key, authorization)
    ts        = datetime.now(timezone.utc).isoformat()
    secret_id = req.get("secret_id","")
    agent_id  = req.get("agent_id","")
    purpose   = req.get("purpose","")
    consequence = req.get("consequence","OPERATIONAL")

    secret = _SECRETS_REGISTRY.get(secret_id)

    reasons = []
    if not secret:
        reasons.append(f"Secret {secret_id} not registered in secrets governance")
    elif secret.get("revoked"):
        reasons.append("Secret has been revoked")
    elif secret.get("permitted_agents") and agent_id not in secret.get("permitted_agents",[]):
        reasons.append(f"Agent {agent_id} not in permitted_agents list for this secret")
    elif secret.get("expires_at") and ts > secret.get("expires_at","9999"):
        reasons.append("Secret has expired — rotation required before further access")

    # Consequence tier check
    TIER_ORDER = ["ADVISORY","OPERATIONAL","HIGH","CRITICAL","EMERGENCY"]
    max_tier   = secret.get("max_consequence","OPERATIONAL") if secret else "ADVISORY"
    if (consequence in TIER_ORDER and max_tier in TIER_ORDER and
            TIER_ORDER.index(consequence) > TIER_ORDER.index(max_tier)):
        reasons.append(
            f"Requested consequence {consequence} exceeds permitted ceiling {max_tier} for this secret"
        )

    ruling = "DENY" if reasons else "ALLOW"

    access_record = {
        "secret_id":  secret_id,
        "agent_id":   agent_id,
        "purpose":    purpose,
        "consequence":consequence,
        "ruling":     ruling,
        "reasons":    reasons,
        "accessed_at":ts,
    }
    _SECRETS_ACCESS_LOG.append(access_record)

    if secret and ruling == "ALLOW":
        secret["access_count"]  = secret.get("access_count",0) + 1
        secret["last_accessed"] = ts

    seal = {"secret_id": secret_id, "agent_id": agent_id, "ruling": ruling, "timestamp": ts}
    return {
        "schema":    "VGS-SECRETS-ACCESS-v1",
        "secret_id": secret_id,
        "agent_id":  agent_id,
        "ruling":    ruling,
        "reasons":   reasons,
        "governance_signature": sign_governance_payload(seal),
        "offline_verifiable":   True,
        "timestamp": ts,
    }


@app.post("/v1/secrets/revoke", tags=["Secrets Governance Layer"])
async def secrets_revoke(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """Revoke a secret — immediately blocks all AI access."""
    require_api_key(x_api_key, authorization)
    ts        = datetime.now(timezone.utc).isoformat()
    secret_id = req.get("secret_id","")
    revoked_by= req.get("revoked_by","")

    if not revoked_by:
        raise HTTPException(status_code=400, detail="revoked_by required — human must authorise revocation")

    secret = _SECRETS_REGISTRY.get(secret_id)
    if not secret:
        raise HTTPException(status_code=404, detail=f"Secret {secret_id} not found")

    secret["revoked"]    = True
    secret["revoked_by"] = revoked_by
    secret["revoked_at"] = ts

    seal = {"secret_id": secret_id, "revoked_by": revoked_by, "timestamp": ts}
    return {
        "secret_id":  secret_id,
        "revoked":    True,
        "revoked_by": revoked_by,
        "revoked_at": ts,
        "effect":     "All AI agents immediately blocked from accessing this secret",
        "governance_signature": sign_governance_payload(seal),
        "timestamp":  ts,
    }


@app.get("/v1/secrets/log", tags=["Secrets Governance Layer"])
async def secrets_log(
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """Complete access log for all secrets — every attempt, ruled or denied."""
    require_api_key(x_api_key, authorization)
    return {
        "total_access_attempts": len(_SECRETS_ACCESS_LOG),
        "total_secrets":         len(_SECRETS_REGISTRY),
        "revoked_secrets":       sum(1 for s in _SECRETS_REGISTRY.values() if s.get("revoked")),
        "recent_access":         _SECRETS_ACCESS_LOG[-20:],
        "timestamp":             datetime.now(timezone.utc).isoformat(),
    }


# ============================================================
# AI SUPPLY CHAIN VERIFICATION
# Expert: "VeriSigil currently governs execution. You could add
# model provenance, model signature verification, model version
# trust, approved model registry before execution. Not antivirus.
# Trust verification."
# ============================================================

_MODEL_REGISTRY: dict = {}  # model_id -> approved model record


@app.post("/v1/model/register", tags=["AI Supply Chain Verification"])
async def model_verify(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    Verify a model is approved for a specific use before execution.
    Called at intercept time when an agent declares its model.
    """
    require_api_key(x_api_key, authorization)
    ts       = datetime.now(timezone.utc).isoformat()
    model_id = req.get("model_id","")
    use_case = req.get("use_case","")
    consequence = req.get("consequence","OPERATIONAL")

    model = _MODEL_REGISTRY.get(model_id)

    reasons = []
    if not model:
        reasons.append(f"Model {model_id} not in approved model registry — register at POST /v1/model/register")
    elif model.get("revoked"):
        reasons.append("Model has been revoked from the approved registry")
    elif model.get("valid_until") and ts > model.get("valid_until","9999"):
        reasons.append("Model approval has expired — re-approval required")
    elif model.get("forbidden_uses") and use_case in model.get("forbidden_uses",[]):
        reasons.append(f"Use case '{use_case}' is in the forbidden uses list for this model")

    TIER_ORDER = ["ADVISORY","OPERATIONAL","HIGH","CRITICAL","EMERGENCY"]
    max_tier   = model.get("max_consequence","OPERATIONAL") if model else "ADVISORY"
    if (consequence in TIER_ORDER and max_tier in TIER_ORDER and
            TIER_ORDER.index(consequence) > TIER_ORDER.index(max_tier)):
        reasons.append(
            f"Consequence {consequence} exceeds model's approved ceiling {max_tier}"
        )

    ruling = "APPROVED" if not reasons else "NOT_APPROVED"

    seal = {"model_id": model_id, "ruling": ruling, "use_case": use_case, "timestamp": ts}
    return {
        "schema":    "VGS-MODEL-VERIFY-v1",
        "model_id":  model_id,
        "use_case":  use_case,
        "consequence":consequence,
        "ruling":    ruling,
        "reasons":   reasons,
        "model_name":model.get("name","") if model else "",
        "provider":  model.get("provider","") if model else "",
        "approved_by":model.get("approved_by","") if model else "",
        "governance_signature": sign_governance_payload(seal),
        "offline_verifiable":   True,
        "timestamp": ts,
    }


@app.get("/v1/model/registry", tags=["AI Supply Chain Verification"])
async def model_registry_list(
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """List all approved AI models in the registry."""
    require_api_key(x_api_key, authorization)
    models  = list(_MODEL_REGISTRY.values())
    active  = [m for m in models if not m.get("revoked")]
    revoked = [m for m in models if m.get("revoked")]
    return {
        "schema":          "VGS-MODEL-REGISTRY-LIST-v1",
        "total_models":    len(models),
        "active_models":   len(active),
        "revoked_models":  len(revoked),
        "models":          active,
        "supply_chain_note": "Only models registered here may be used by AI agents in governed actions.",
        "timestamp":       datetime.now(timezone.utc).isoformat(),
    }


@app.post("/v1/model/revoke", tags=["AI Supply Chain Verification"])
async def model_revoke(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """Revoke a model — immediately blocks all agents from using it in governed actions."""
    require_api_key(x_api_key, authorization)
    ts        = datetime.now(timezone.utc).isoformat()
    model_id  = req.get("model_id","")
    revoked_by= req.get("revoked_by","")
    reason    = req.get("reason","")

    if not revoked_by:
        raise HTTPException(status_code=400, detail="revoked_by required")

    model = _MODEL_REGISTRY.get(model_id)
    if not model:
        raise HTTPException(status_code=404, detail=f"Model {model_id} not found")

    model["revoked"]    = True
    model["revoked_by"] = revoked_by
    model["revoked_at"] = ts
    model["revoke_reason"] = reason

    seal = {"model_id": model_id, "revoked_by": revoked_by, "timestamp": ts}
    return {
        "model_id":   model_id,
        "revoked":    True,
        "revoked_by": revoked_by,
        "reason":     reason,
        "effect":     "All AI agents immediately blocked from using this model in governed actions",
        "governance_signature": sign_governance_payload(seal),
        "timestamp":  ts,
    }



# ============================================================
# CONTENT TRANSPARENCY & PROVENANCE LAYER
# Expert: "Don't only record that disclosure occurred.
# Make the disclosure technically inspectable."
#
# Architectural lesson from Hardin AI / TBN Certify:
# Detection ≠ Governance.
# A detector says "this appears AI-generated."
# VeriSigil says:
#   Was this AI use authorized?
#   Was disclosure required?
#   Who approved it?
#   Was the correct disclosure applied?
#   Was the content altered after certification?
#   Did the organization have authority to release it?
#
# The Content Governance Certificate answers all seven.
# It does not replace detection — it governs what happens
# after detection and makes the governance decision provable.
#
# Workflow:
# Detect/Provenance Signal
# → VeriSigil Content Intake
# → Disclosure & Regulatory Rules
# → Authority + Approval + Jurisdiction Check
# → Visible Label + Machine-Readable Provenance
# → Cryptographic Certificate / Governance Receipt
# → Verification Registry
# → Release / Distribution
# ============================================================

_CONTENT_CERTIFICATES: dict = {}  # certificate_id -> certificate


@app.post("/v1/provenance/certify", tags=["Content Transparency & Provenance"])
async def provenance_certify(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    VeriSigil Content Governance Certificate.

    Issues a cryptographically signed, independently verifiable
    certificate proving that AI-generated content was:

    1. Identified as AI-generated
    2. Reviewed by a named human authority
    3. Disclosed under the applicable regulation
    4. Authorized for release under the governing policy
    5. Sealed before distribution

    This is complementary to detection tools like TBN Certify.
    Detection answers: "Is this AI-generated?"
    VeriSigil answers: "Was the decision to release it properly
    authorized, disclosed, and governed before it left?"

    Supports: EU AI Act Article 50, California SB 942,
    UK AI Code of Practice, and custom jurisdiction rules.

    The certificate is independently verifiable at:
    GET /v1/provenance/verify/{certificate_id}
    No trust in VeriSigil required.
    """
    require_api_key(x_api_key, authorization)
    ts             = datetime.now(timezone.utc).isoformat()
    certificate_id = f"CGC-{hashlib.sha256(ts.encode()).hexdigest()[:16].upper()}"

    # Content identification
    content_raw    = req.get("content","")
    content_hash   = hashlib.sha256(
        json.dumps(content_raw, sort_keys=True, separators=(",",":")).encode()
    ).hexdigest() if content_raw else req.get("content_hash","")

    ai_generated   = req.get("ai_generated", False)
    ai_model       = req.get("ai_model","")
    ai_provider    = req.get("ai_provider","")
    ai_involvement = req.get("ai_involvement","")  # DRAFTED, SUMMARISED, DECIDED, ENHANCED, GENERATED
    content_type   = req.get("content_type","")    # TEXT, IMAGE, VIDEO, AUDIO, DOCUMENT
    jurisdiction   = req.get("jurisdiction","EU")

    # Governance fields
    approved_by       = req.get("approved_by","")
    approver_role     = req.get("approver_role","")
    governing_policy  = req.get("governing_policy","")
    disclosure_method = req.get("disclosure_method","")
    disclosure_label  = req.get("disclosure_label","")
    org_id            = req.get("org_id","")
    release_destination = req.get("release_destination","")

    # External detection reference
    detection_provider = req.get("detection_provider","")
    detection_cert_id  = req.get("detection_certificate_id","")
    detection_score    = req.get("ai_detection_score", None)

    # Regulatory compliance checks
    compliance_issues = []
    if ai_generated and not disclosure_method:
        compliance_issues.append(f"Disclosure method required under {jurisdiction}")
    if ai_generated and not approved_by:
        compliance_issues.append("Human approver required before release")
    if jurisdiction in ("EU","UK") and content_type in ("IMAGE","VIDEO") and not disclosure_label:
        compliance_issues.append(f"Article 50(4): visible label required for AI-generated {content_type}")
    if jurisdiction in ("US","CA","SB942") and not disclosure_method:
        compliance_issues.append("SB 942 §3: visible disclosure required for AI-generated content")
    if jurisdiction in ("US","CA","SB942") and not req.get("machine_readable_metadata"):
        compliance_issues.append("SB 942 §3(b): machine-readable metadata required")

    compliant = len(compliance_issues) == 0

    # Build the certificate
    certificate = {
        "schema":             "VGS-CONTENT-GOVERNANCE-CERTIFICATE-v1",
        "certificate_id":     certificate_id,
        "certificate_type":   "CRYPTOGRAPHIC_GOVERNANCE_CERTIFICATE",

        # Content identification
        "content_hash":       content_hash,
        "content_type":       content_type,

        # AI provenance
        "ai_generated":       ai_generated,
        "ai_model":           ai_model,
        "ai_provider":        ai_provider,
        "ai_involvement":     ai_involvement,

        # Disclosure
        "disclosure_method":  disclosure_method,
        "disclosure_label":   disclosure_label,
        "jurisdiction":       jurisdiction,

        # Governance decision
        "approved_by":        approved_by,
        "approver_role":      approver_role,
        "governing_policy":   governing_policy,
        "org_id":             org_id,
        "release_destination":release_destination,

        # External detection reference (complementary — not required)
        "detection_provider":    detection_provider,
        "detection_cert_id":     detection_cert_id,
        "detection_score":       detection_score,
        "detection_note":        (
            "External detection certificate reference. "
            "Detection answers 'Is this AI-generated?' "
            "This certificate answers 'Was the governance decision to release it properly authorized?'"
        ),

        # Compliance assessment
        "regulatory_compliant":  compliant,
        "compliance_issues":     compliance_issues,
        "ruling":                "AUTHORIZED FOR RELEASE" if compliant else "NOT AUTHORIZED — resolve compliance issues",

        # Machine-readable provenance block (the technically inspectable disclosure)
        "machine_readable_provenance": {
            "certificate_id":      certificate_id,
            "content_hash":        content_hash,
            "ai_generated":        ai_generated,
            "ai_model":            ai_model,
            "ai_provider":         ai_provider,
            "ai_involvement":      ai_involvement,
            "disclosure_status":   "DISCLOSED" if (disclosure_method and approved_by) else "NOT_DISCLOSED",
            "disclosure_method":   disclosure_method,
            "jurisdiction":        jurisdiction,
            "governing_policy":    governing_policy,
            "responsible_org":     org_id,
            "approval_authority":  approved_by,
            "approver_role":       approver_role,
            "verification_status": "COMPLIANT" if compliant else "NON_COMPLIANT",
            "issued_at":           ts,
            "verify_at":           f"GET /v1/provenance/verify/{certificate_id}",
        },

        "issued_at":  ts,
        "valid_until": req.get("valid_until",""),
    }

    # Seal the certificate
    seal = {
        "certificate_id": certificate_id,
        "content_hash":   content_hash,
        "ai_generated":   ai_generated,
        "compliant":      compliant,
        "approved_by":    approved_by,
        "timestamp":      ts,
    }
    certificate["governance_signature"] = sign_governance_payload(seal)
    certificate["offline_verifiable"]   = True
    certificate["public_key"]           = "lJWG0Wabt6uATPu5Upo6UEHWGXQqMyi6LMKQC0xwpY8="
    certificate["verify_url"]           = f"GET /v1/provenance/verify/{certificate_id}"

    _CONTENT_CERTIFICATES[certificate_id] = certificate

    if not compliant:
        _BOARD_EVENTS.append({
            "type":           "CONTENT_NOT_AUTHORIZED",
            "certificate_id": certificate_id,
            "org_id":         org_id,
            "issues":         compliance_issues,
            "at":             ts,
        })

    return {
        **certificate,
        "governance_note": (
            "This is a Cryptographically Verifiable Governance Certificate. "
            "It proves that governance controls were applied before release — "
            "not that the organisation is legally compliant with any regulation. "
            "Regulatory compliance is determined by the applicable authority. "
            "The governance signature is independently verifiable without trusting VeriSigil. "
            "Present as evidence of governance execution to regulators on demand."
        ),
        "overclaim_warning": (
            "Do not describe this as an 'EU AI Act Compliance Certificate' or "
            "'SB 942 Compliance Certificate'. VeriSigil proves governance execution — "
            "not regulatory compliance. That distinction matters legally."
        ),
    }


@app.get("/v1/provenance/verify/{certificate_id}", tags=["Content Transparency & Provenance"])
async def provenance_verify(certificate_id: str):
    """
    Verify a VeriSigil Content Governance Certificate.

    No authentication required. Anyone can verify.
    The verifier does not need to trust VeriSigil — they verify
    the Ed25519 signature using the published public key.

    Returns: certificate status, governance signature, content hash,
    AI provenance, compliance status, and offline verification instructions.

    Public key: lJWG0Wabt6uATPu5Upo6UEHWGXQqMyi6LMKQC0xwpY8=
    """
    cert = _CONTENT_CERTIFICATES.get(certificate_id)
    if not cert:
        return {
            "certificate_id": certificate_id,
            "status":         "NOT_FOUND",
            "note":           "Certificate not found. May have been issued on a different server instance (in-memory store). For production use, certificates should be stored in a persistent ledger.",
            "timestamp":      datetime.now(timezone.utc).isoformat(),
        }

    return {
        "certificate_id":      certificate_id,
        "status":              "VERIFIED" if cert.get("regulatory_compliant") else "NON_COMPLIANT",
        "content_hash":        cert.get("content_hash",""),
        "ai_generated":        cert.get("ai_generated"),
        "ai_model":            cert.get("ai_model",""),
        "ai_involvement":      cert.get("ai_involvement",""),
        "disclosure_method":   cert.get("disclosure_method",""),
        "jurisdiction":        cert.get("jurisdiction",""),
        "approved_by":         cert.get("approved_by",""),
        "regulatory_compliant":cert.get("regulatory_compliant"),
        "compliance_issues":   cert.get("compliance_issues",[]),
        "governance_signature":cert.get("governance_signature",""),
        "issued_at":           cert.get("issued_at",""),
        "offline_verify": (
            "from nacl.signing import VerifyKey; import base64, hashlib, json; "
            "payload = json.dumps(seal_dict, sort_keys=True, separators=(',',':')).encode(); "
            "VerifyKey(base64.b64decode(public_key)).verify(payload, base64.b64decode(signature))"
        ),
        "public_key":          "lJWG0Wabt6uATPu5Upo6UEHWGXQqMyi6LMKQC0xwpY8=",
        "timestamp":           datetime.now(timezone.utc).isoformat(),
    }


@app.get("/v1/provenance/registry", tags=["Content Transparency & Provenance"])
async def provenance_registry(
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """All issued Content Governance Certificates with compliance summary."""
    require_api_key(x_api_key, authorization)
    certs     = list(_CONTENT_CERTIFICATES.values())
    compliant = sum(1 for c in certs if c.get("regulatory_compliant"))
    return {
        "schema":            "VGS-CONTENT-REGISTRY-v1",
        "total_certificates":len(certs),
        "compliant":         compliant,
        "non_compliant":     len(certs) - compliant,
        "compliance_rate":   round(compliant / max(len(certs),1), 3),
        "recent":            certs[-20:],
        "timestamp":         datetime.now(timezone.utc).isoformat(),
    }



