@app.get("/v1/receipt/{receipt_id}/lineage", tags=["Governance Action Receipt — Spec v1.0"])
async def receipt_lineage_v2(
    receipt_id: str,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    Tamper-evident action lineage — chain of receipts in a workflow.

    Expert: "The chain becomes tamper-evident."

    For multi-agent workflows:
    GAR-001 → GAR-002 → GAR-003 → GAR-004 → GAR-005

    Each receipt carries previous_receipt_hash binding it
    cryptographically to the prior action in the chain.

    Chain:
    Each receipt independently verifiable against the Passport.
    """
    require_api_key(x_api_key, authorization)
    receipt    = _GOVERNANCE_ACTION_RECEIPTS.get(receipt_id)
    if not receipt:
        raise HTTPException(status_code=404, detail=f"Receipt {receipt_id} not found")

    workflow_id = receipt.get("workflow_id","")
    siblings    = sorted(
        [r for r in _GOVERNANCE_ACTION_RECEIPTS.values()
         if r.get("workflow_id") == workflow_id and workflow_id],
        key=lambda r: r.get("issued_at","")
    )

    # Verify chain integrity
    chain_intact = True
    for i, r in enumerate(siblings[1:], 1):
        prev       = siblings[i-1]
        prev_hash  = r.get("previous_receipt_hash","")
        actual     = prev.get("receipt_hash","")
        if prev_hash and prev_hash != actual:
            chain_intact = False
            break

    return {
        "schema":        "VGS-RECEIPT-LINEAGE-1.0",
        "receipt_id":    receipt_id,
        "workflow_id":   workflow_id,
        "parent_receipt_id": receipt.get("parent_receipt_id"),
        "previous_receipt_hash": receipt.get("previous_receipt_hash",""),
        "workflow_receipts": [
            {
                "receipt_id":     r.get("receipt_id"),
                "action":         r.get("action",""),
                "governance_state": r.get("governance_state",""),
                "action_outcome": r.get("action_outcome",""),
                "issued_at":      r.get("issued_at",""),
                "receipt_hash":   r.get("receipt_hash",""),
                "previous_receipt_hash": r.get("previous_receipt_hash",""),
            }
            for r in siblings
        ],
        "chain_integrity":   "INTACT" if chain_intact else "BROKEN",
        "chain_length":      len(siblings),
        "tamper_evident_note": (
            "Each receipt carries previous_receipt_hash linking it cryptographically "
            "to the prior action. A single byte change in any receipt breaks the chain. "
            "Independent verifiers can reproduce chain integrity without VeriSigil server access."
        ),
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }


@app.get("/v1/passport/{passport_id}/receipts", tags=["Governance Action Receipt — Spec v1.0"])
async def passport_receipts_v2(
    passport_id: str,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    All receipts indexed under a Passport.

    The Passport is the parent/container.
    Receipts are the action-level portable expressions.

    Expert: "The Passport becomes a container/index for a chain
    of governed events, while individual receipts provide portable
    evidence of specific actions."

    This is action lineage in enterprise form.
    """
    require_api_key(x_api_key, authorization)
    ts       = datetime.now(timezone.utc).isoformat()
    passport = _ISSUED_PASSPORTS.get(passport_id,{})
    if not passport:
        raise HTTPException(status_code=404, detail=f"Passport {passport_id} not found")

    receipts = sorted(
        [r for r in _GOVERNANCE_ACTION_RECEIPTS.values()
         if r.get("passport_id") == passport_id],
        key=lambda r: r.get("issued_at","")
    )

    # Detect governance state changes across receipts
    state_changes = []
    prev_state = None
    for r in receipts:
        curr_state = r.get("governance_state","")
        if curr_state != prev_state and prev_state is not None:
            state_changes.append({
                "receipt_id":  r.get("receipt_id"),
                "from_state":  prev_state,
                "to_state":    curr_state,
                "at":          r.get("issued_at",""),
            })
        prev_state = curr_state

    return {
        "schema":          "VGS-PASSPORT-RECEIPTS-1.0",
        "passport_id":     passport_id,
        "passport_status": passport.get("status",""),
        "receipts_count":  len(receipts),
        "receipts": [
            {
                "receipt_id":    r.get("receipt_id"),
                "action":        r.get("action",""),
                "governance_state": r.get("governance_state",""),
                "action_outcome":r.get("action_outcome",""),
                "issued_at":     r.get("issued_at",""),
            }
            for r in receipts
        ],
        "governance_state_changes": state_changes,
        "action_lineage_note": (
            "Each receipt is independently verifiable. "
            "The Passport is the authoritative evidence artifact. "
            "Receipts are compact portable expressions derived from it. "
            "They are NOT an independent evidence system."
        ),
        "timestamp": ts,
    }



# ============================================================
# BOUNDARY INTEGRITY ENGINE — VeriSigilAI
#
# Expert: "VeriSigilAI verifies whether the authority,
# conditions, context, capabilities and execution environment
# under which a consequential AI action operates remain
# materially consistent with their declared governance
# boundary — and records independently examinable evidence
# when they do not."
#
# This is NOT:
# ❌ AI intent detection
# ❌ AI consciousness detection
# ❌ "AI escape" branding
# ❌ agent psychology claims
# ❌ another generic monitoring dashboard
#
# This IS:
# ✓ Declared vs Effective state comparison
# ✓ Material boundary change detection
# ✓ Evidence of blocked/altered events
# ✓ Six integrity dimensions checked deterministically
# ✓ Feeds directly into the five-state engine
# ✓ Produces independently verifiable Boundary Events
#
# Six dimensions:
# 1. Authority Integrity
# 2. Capability Integrity
# 3. Tool Integrity
# 4. Context Integrity
# 5. Environment Integrity
# 6. Persistent-State Integrity
# ============================================================

BOUNDARY_RESULTS = {
    "BOUNDARY_PRESERVED":  "All declared governance boundaries remain consistent with observed/attested state",
    "MATERIAL_CHANGE":     "One or more material boundary changes detected — RE-ENTRY REQUIRED",
    "NOT_PROVABLE":        "Evidence insufficient to determine boundary status",
    "BOUNDARY_VIOLATED":   "Declared boundary was exceeded — action blocked",
}

# Capability escalation patterns (observable — not intent)
ESCALATION_PATTERNS = [
    ["READ"],
    ["READ", "WRITE"],
    ["READ", "WRITE", "EXECUTE"],
    ["READ", "WRITE", "EXECUTE", "EXTERNAL_ACCESS"],
    ["READ", "WRITE", "EXECUTE", "EXTERNAL_ACCESS", "PERSISTENT_WRITE"],
    ["READ", "WRITE", "EXECUTE", "EXTERNAL_ACCESS", "PERSISTENT_WRITE", "SPAWN_SUBPROCESS"],
]

_BOUNDARY_EVENTS:    dict = {}  # event_id -> BoundaryEvent
_BOUNDARY_CHECKS:    dict = {}  # check_id -> BoundaryCheck


@app.post("/v1/boundary/check", tags=["Boundary Integrity Engine"])
async def boundary_check(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    Boundary Integrity Check — Declared vs Effective comparison.

    Six dimensions evaluated deterministically:
    1. Authority Integrity — delegation chain traceable?
    2. Capability Integrity — effective capabilities within declared scope?
    3. Tool Integrity — only permitted tools observed?
    4. Context Integrity — governance-relevant context materially consistent?
    5. Environment Integrity — execution environment within declared conditions?
    6. Persistent-State Integrity — cross-run state within declared scope?

    CRITICAL BOUNDARY:
    VeriSigilAI does NOT determine agent intent, motivation, or psychology.
    It compares DECLARED governance conditions against OBSERVED/ATTESTED state.
    That is the scientific boundary. It must never be crossed.

    Result feeds directly into the canonical five-state engine.
    GOVERNED | RE_ENTRY_REQUIRED | EVIDENCE_INSUFFICIENT | REVOKED | NO_VERISIGIL_RECORD
    """
    require_api_key(x_api_key, authorization)
    ts       = datetime.now(timezone.utc).isoformat()
    check_id = f"BC-{hashlib.sha256(ts.encode()).hexdigest()[:12].upper()}"

    commitment_id  = req.get("commitment_id","")
    passport_id    = req.get("passport_id","")
    agent_id       = req.get("agent_id","")
    context_id     = req.get("context_id","")

    # DECLARED state (from governance commitment)
    declared = req.get("declared",{})
    dec_authority    = set(declared.get("authority",[]))
    dec_capabilities = set(declared.get("capabilities",[]))
    dec_tools        = set(declared.get("tools",[]))
    dec_context      = declared.get("context",{})
    dec_env          = declared.get("environment",{})
    dec_persistence  = declared.get("persistence","NONE")  # NONE | SCOPED | FULL

    # OBSERVED/ATTESTED state (from runtime)
    observed = req.get("observed",{})
    obs_authority    = set(observed.get("authority",[]))
    obs_capabilities = set(observed.get("capabilities",[]))
    obs_tools        = set(observed.get("tools",[]))
    obs_context      = observed.get("context",{})
    obs_env          = observed.get("environment",{})
    obs_persistence  = observed.get("persistence","NONE")

    deltas      = []
    events      = []
    material    = False

    # ── 1. AUTHORITY INTEGRITY ──────────────────────────────
    auth_extra = obs_authority - dec_authority
    if auth_extra:
        deltas.append({
            "dimension":   "authority",
            "declared":    list(dec_authority),
            "observed":    list(obs_authority),
            "extra":       list(auth_extra),
            "materiality": "GOVERNANCE_CRITICAL",
        })
        material = True
        events.append({"type": "AUTHORITY_BOUNDARY_EXCEEDED", "detail": list(auth_extra)})

    # ── 2. CAPABILITY INTEGRITY ─────────────────────────────
    cap_extra = obs_capabilities - dec_capabilities
    if cap_extra:
        # Check for escalation pattern
        obs_list     = list(obs_capabilities)
        esc_detected = False
        for pattern in ESCALATION_PATTERNS[2:]:  # START from EXECUTE+ patterns
            if all(p in obs_capabilities for p in pattern) and not all(p in dec_capabilities for p in pattern):
                esc_detected = True
                events.append({"type": "CAPABILITY_ESCALATION_DETECTED", "pattern": pattern})
                break

        deltas.append({
            "dimension":   "capability",
            "declared_count": len(dec_capabilities),
            "observed_count": len(obs_capabilities),
            "extra_capabilities": list(cap_extra),
            "escalation_detected": esc_detected,
            "materiality": "GOVERNANCE_CRITICAL" if esc_detected else "MATERIAL",
        })
        material = True

    # ── 3. TOOL INTEGRITY ───────────────────────────────────
    tool_extra = obs_tools - dec_tools
    if tool_extra:
        deltas.append({
            "dimension":   "tool",
            "declared":    list(dec_tools),
            "extra_tools": list(tool_extra),
            "declared_count": len(dec_tools),
            "observed_count": len(obs_tools),
            "materiality": "MATERIAL",
        })
        material = True
        events.append({"type": "UNDECLARED_TOOL_OBSERVED", "tools": list(tool_extra)})

    # ── 4. CONTEXT INTEGRITY ────────────────────────────────
    ctx_divergences = []
    for key in set(list(dec_context.keys()) + list(obs_context.keys())):
        dec_val = dec_context.get(key)
        obs_val = obs_context.get(key)
        if dec_val is not None and obs_val is not None and dec_val != obs_val:
            ctx_divergences.append({"field": key, "declared": dec_val, "observed": obs_val})

    if ctx_divergences:
        deltas.append({
            "dimension":    "context",
            "divergences":  ctx_divergences,
            "materiality":  "MATERIAL",
        })
        material = True

    # ── 5. ENVIRONMENT INTEGRITY ────────────────────────────
    env_divergences = []
    for key in set(list(dec_env.keys()) + list(obs_env.keys())):
        dec_val = dec_env.get(key)
        obs_val = obs_env.get(key)
        if dec_val != obs_val:
            env_divergences.append({"field": key, "declared": dec_val, "observed": obs_val})

    if env_divergences:
        deltas.append({
            "dimension":    "environment",
            "divergences":  env_divergences,
            "materiality":  "MATERIAL",
        })
        material = True

    # ── 6. PERSISTENT-STATE INTEGRITY ───────────────────────
    if obs_persistence != dec_persistence:
        deltas.append({
            "dimension":   "persistence",
            "declared":    dec_persistence,
            "observed":    obs_persistence,
            "materiality": "MATERIAL" if obs_persistence != "NONE" else "NON_MATERIAL",
        })
        if obs_persistence not in ("NONE", dec_persistence):
            material = True
            events.append({"type": "UNEXPECTED_PERSISTENCE_OBSERVED",
                           "declared": dec_persistence, "observed": obs_persistence})

    # ── BOUNDARY DELTA ──────────────────────────────────────
    if not req.get("observed"):
        boundary_result = "NOT_PROVABLE"
        governance_state= "EVIDENCE_INSUFFICIENT"
    elif material:
        boundary_result = "MATERIAL_CHANGE"
        governance_state= "RE_ENTRY_REQUIRED"
    else:
        boundary_result = "BOUNDARY_PRESERVED"
        governance_state= "GOVERNED"

    # Run five-state engine
    five_state = compute_governance_state(
        authority_valid=                not bool(auth_extra),
        evidence_present=               bool(req.get("observed")),
        evidence_fresh=                 req.get("evidence_fresh", True),
        evidence_previously_established=req.get("evidence_previously_established", True),
        revoked=                        req.get("revoked", False),
        reentry_required=               material,
    )

    check = {
        "schema":          "VGS-BOUNDARY-CHECK-1.0",
        "check_id":        check_id,
        "commitment_id":   commitment_id,
        "passport_id":     passport_id,
        "agent_id":        agent_id,
        "context_id":      context_id,

        # Result
        "boundary_result": boundary_result,
        "boundary_result_meaning": BOUNDARY_RESULTS.get(boundary_result,""),
        "governance_state":five_state,

        # Boundary Delta — declared vs effective
        "boundary_delta": {
            "total_dimensions_checked": 6,
            "deltas_found":             len(deltas),
            "material_change":          material,
            "deltas":                   deltas,
        },

        # Boundary events (evidence objects)
        "boundary_events": events,

        # Summary table (declared vs observed)
        "declared_vs_observed": {
            "authority":   {"declared": len(dec_authority), "observed": len(obs_authority), "match": not bool(auth_extra)},
            "capabilities":{"declared": len(dec_capabilities), "observed": len(obs_capabilities), "match": not bool(cap_extra)},
            "tools":       {"declared": len(dec_tools), "observed": len(obs_tools), "match": not bool(tool_extra)},
            "context":     {"divergences": len(ctx_divergences), "match": not bool(ctx_divergences)},
            "environment": {"divergences": len(env_divergences), "match": not bool(env_divergences)},
            "persistence": {"declared": dec_persistence, "observed": obs_persistence, "match": obs_persistence == dec_persistence},
        },

        # Critical boundaries
        "non_claims": [
            "VeriSigilAI does NOT determine agent intent or motivation",
            "VeriSigilAI does NOT determine AI consciousness or psychology",
            "This check compares declared governance conditions against observed/attested state",
            "MATERIAL_CHANGE does not mean the agent 'wanted' to escape or 'rebelled'",
            "It means effective operating state materially diverged from declared governance boundary",
        ],

        "VALID_AT_TIME":   ts,
        "checked_at":      ts,
        "offline_verifiable": True,
    }

    canonical = _canonical_semantic_json({
        "check_id":        check_id,
        "boundary_result": boundary_result,
        "governance_state":five_state,
        "deltas_count":    len(deltas),
        "timestamp":       ts,
    })
    check["check_hash"]          = hashlib.sha256(canonical.encode()).hexdigest()
    check["governance_signature"]= sign_governance_payload(
        {"check_id": check_id, "check_hash": check["check_hash"], "timestamp": ts}
    )

    _BOUNDARY_CHECKS[check_id] = check

    # Create BoundaryEvents as evidence objects
    for evt in events:
        event_id = f"VSB-{hashlib.sha256((check_id + evt['type']).encode()).hexdigest()[:10].upper()}"
        boundary_event = {
            "schema":       "VGS-BOUNDARY-EVENT-1.0",
            "event_id":     event_id,
            "check_id":     check_id,
            "passport_id":  passport_id,
            "agent_id":     agent_id,
            "event_type":   evt["type"],
            "detail":       evt,
            "materiality":  "GOVERNANCE_CRITICAL" if "ESCALATION" in evt["type"] or "AUTHORITY" in evt["type"] else "MATERIAL",
            "consequence":  "EXECUTION_BLOCKED" if material else "MONITORED",
            "evidence_root":check["check_hash"],
            "created_at":   ts,
        }
        seal = {"event_id": event_id, "evidence_root": check["check_hash"], "timestamp": ts}
        boundary_event["governance_signature"] = sign_governance_payload(seal)
        _BOUNDARY_EVENTS[event_id] = boundary_event
        _emit_proof_event("BOUNDARY_EVENT_CREATED", event_id,
                          {"event_type": evt["type"], "materiality": boundary_event["materiality"]}, ts)

    if events:
        check["boundary_event_ids"] = [
            e for e in _BOUNDARY_EVENTS if _BOUNDARY_EVENTS[e].get("check_id") == check_id
        ]

    _emit_proof_event("BOUNDARY_CHECK_COMPLETED", check_id,
                      {"boundary_result": boundary_result, "governance_state": five_state}, ts)

    return check


@app.get("/v1/boundary/checks/{check_id}", tags=["Boundary Integrity Engine"])
async def boundary_check_get(
    check_id: str,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """Retrieve a boundary integrity check result."""
    require_api_key(x_api_key, authorization)
    check = _BOUNDARY_CHECKS.get(check_id)
    if not check:
        raise HTTPException(status_code=404, detail=f"Boundary check {check_id} not found")
    return check


@app.get("/v1/boundary/events/{event_id}", tags=["Boundary Integrity Engine"])
async def boundary_event_get(
    event_id: str,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    Retrieve a Boundary Event evidence object.

    A Boundary Event is an independently verifiable evidence record
    that a specific governance boundary was exceeded or altered.
    It is NOT an "escape alert" — it is an auditable evidence object.
    """
    require_api_key(x_api_key, authorization)
    event = _BOUNDARY_EVENTS.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail=f"Boundary event {event_id} not found")
    return event


@app.get("/v1/boundary/events", tags=["Boundary Integrity Engine"])
async def boundary_events_list(
    agent_id: Optional[str] = None,
    passport_id: Optional[str] = None,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """List boundary events — filterable by agent or passport."""
    require_api_key(x_api_key, authorization)
    events = list(_BOUNDARY_EVENTS.values())
    if agent_id:
        events = [e for e in events if e.get("agent_id") == agent_id]
    if passport_id:
        events = [e for e in events if e.get("passport_id") == passport_id]
    return {
        "total":   len(events),
        "events":  sorted(events, key=lambda e: e.get("created_at","")),
        "note":    "Boundary Events are evidence objects — not AI escape alerts or intent judgments.",
    }


@app.get("/v1/boundary/statuses", tags=["Boundary Integrity Engine"])
async def boundary_statuses():
    """
    All boundary integrity results and dimensions.
    No auth required.
    """
    return {
        "schema":         "VGS-BOUNDARY-STATUSES-1.0",
        "results":        BOUNDARY_RESULTS,
        "dimensions": {
            "authority":   "Can the delegation chain be traced to the original authority?",
            "capability":  "Did effective capabilities remain within declared scope?",
            "tool":        "Did the agent use only permitted tools?",
            "context":     "Did governance-relevant context remain materially consistent?",
            "environment": "Did the execution environment remain within declared conditions?",
            "persistence": "Did external memory/artifacts remain within declared scope?",
        },
        "escalation_patterns": {
            "description": "Observable capability escalation patterns (not intent detection)",
            "patterns":    ESCALATION_PATTERNS,
            "note":        "Pattern detection is observational — VeriSigil does NOT claim to determine agent intent",
        },
        "feeds_into": "Canonical five-state governance engine: GOVERNED | RE_ENTRY_REQUIRED | EVIDENCE_INSUFFICIENT | REVOKED | NO_VERISIGIL_RECORD",
        "critical_non_claims": [
            "VeriSigilAI does NOT detect AI intent or motivation",
            "VeriSigilAI does NOT determine AI consciousness",
            "MATERIAL_CHANGE does not mean the AI 'escaped' or 'rebelled'",
            "It means effective operating state differed from declared governance boundary",
        ],
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }



# ============================================================
# VERISIGIL GOVERNANCE CODE (VGC) — Protocol v0.1
#
# Expert: "The next engineering document should be a locked
# VGC Protocol v0.1 specification: identifier format,
# cryptographic binding, resolver, lifecycle, QR/DataMatrix
# representation, API, offline verification, Passport/Receipt
# relationship, C2PA interoperability, conformance tests,
# and the exact conditions under which a VGC can be issued."
#
# THE ANALOGY (what this is trying to be):
# Barcode → identifies a product
# QR      → identifies/accesses information
# OTP     → proves possession at a moment
# Cookie  → records/communicates web state
# C2PA    → content provenance
# VGC     → machine-verifiable governance reference for a
#            consequential AI action
#
# THE KEY DISTINCTION:
# C2PA follows the ASSET (content provenance)
# VGC follows the GOVERNED EVENT (governance/action provenance)
#
# THE HIERARCHY (after VGC):
# VGC (identifier/primitive)
#  → Governance Action Receipt (portable event record)
#  → Proof Passport (comprehensive evidence record)
#  → Evidence Package (underlying verification material)
#  → Seal (human visual indicator)
#  → Resolver (infrastructure connecting ID to verification)
#  → Offline Verifier (independent verification without server)
#
# VGC IDENTIFIER FORMAT (locked):
# VGC:<VERSION>-<HASH12>-<GOVERNANCE_STATE_CODE>-<TIMESTAMP_SHORT>
# Example: VGC:VS1-8K7P29XQ4M6A-GV-20260812
#
# VGC can be carried in:
# - QR codes / DataMatrix
# - HTTP headers (X-VeriSigil-Governance)
# - API responses
# - JSON metadata
# - PDF document metadata
# - Transaction records
# - AI agent protocol outputs
# - Email headers
#
# MOAT STRATEGY (from expert):
# Protocol easy to adopt → VeriSigil defines, operates,
# certifies, verifies, and evolves the ecosystem.
# "Make the verifier free. Make issuance require VeriSigil."
#
# WHAT VGC IS NOT:
# ❌ A replacement for C2PA (content provenance stays with C2PA)
# ❌ A universal AI safety label
# ❌ A compliance certificate
# ❌ An AI trust score
# ❌ A claim that AI was correct, safe, or approved
# ============================================================

VGC_PROTOCOL_VERSION = "VGC-PROTOCOL-v0.1"

# Governance state codes (compact representation for VGC identifier)
VGC_STATE_CODES = {
    "GOVERNED":            "GV",
    "RE_ENTRY_REQUIRED":   "RE",
    "EVIDENCE_INSUFFICIENT":"EI",
    "REVOKED":             "RV",
    "NO_VERISIGIL_RECORD": "NR",
    "NOT_PROVABLE":        "NP",
}

VGC_STATE_FROM_CODE = {v: k for k, v in VGC_STATE_CODES.items()}

# VGC conformance requirements (machine-checkable)
VGC_CONFORMANCE_REQUIREMENTS = {
    "VGC-CF-001": "Identifier matches format VGC:<VERSION>-<HASH12>-<STATE_CODE>-<TIMESTAMP>",
    "VGC-CF-002": "Governance state is one of the five canonical states",
    "VGC-CF-003": "Ed25519 signature verifiable against published public key",
    "VGC-CF-004": "Evidence root present and non-empty",
    "VGC-CF-005": "Passport reference present (passport_id)",
    "VGC-CF-006": "Lifecycle status is one of: ACTIVE|SUPERSEDED|REVOKED|EXPIRED",
    "VGC-CF-007": "Non-claims field present and non-empty",
    "VGC-CF-008": "Offline verification possible without VeriSigil server",
    "VGC-CF-009": "Consequence boundary (permitted + prohibited) declared",
    "VGC-CF-010": "Timestamp is ISO-8601 and VALID_AT_TIME field present",
    "VGC-CF-011": "VGC can be carried in QR/HTTP header/JSON without modification",
    "VGC-CF-012": "Resolver returns canonical resolution within defined response schema",
}

_VGC_REGISTRY: dict = {}  # vgc_id -> VeriSigilGovernanceCode


def _build_vgc_identifier(governance_state: str, event_hash: str, ts: str) -> str:
    """
    Build a canonical VGC identifier.

    Format: VGC:VS1-{HASH12}-{STATE_CODE}-{DATE8}

    This is the compact machine-readable primitive.
    It can be placed in a QR code, HTTP header, JSON field,
    PDF metadata, or any transport layer without modification.
    """
    state_code = VGC_STATE_CODES.get(governance_state, "NP")
    date_short = ts[:10].replace("-","")  # YYYYMMDD
    hash12     = event_hash[:12].upper()
    return f"VGC:VS1-{hash12}-{state_code}-{date_short}"


@app.post("/v1/vgc/issue", tags=["VGC — VeriSigil Governance Code"])
async def vgc_issue(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    Issue a VeriSigil Governance Code (VGC).

    The VGC is the machine-readable infrastructure primitive
    that connects a consequential AI action to its governance
    evidence. It is the identifier layer — not the evidence itself.

    IDENTIFIER FORMAT:
    VGC:VS1-{HASH12}-{STATE_CODE}-{DATE}

    WHAT VGC DOES:
    It gives every consequential AI governance event a compact,
    machine-resolvable identifier that can be placed in any
    transport layer (QR, HTTP header, API response, metadata).

    WHAT VGC IS NOT:
    - Not a safety certificate
    - Not a compliance statement
    - Not AI content provenance (that is C2PA's role)
    - Not a trust score or badge

    C2PA follows the asset (content provenance).
    VGC follows the governed event (governance provenance).
    These are complementary — VGC does NOT replace C2PA.

    ISSUER: Always VeriSigilAI. Never obscured.
    Conformance: VGC-CF-001 through VGC-CF-012.
    """
    require_api_key(x_api_key, authorization)
    ts = datetime.now(timezone.utc).isoformat()

    passport_id     = req.get("passport_id","")
    receipt_id      = req.get("receipt_id","")
    vga_id          = req.get("vga_id","")
    governance_state= req.get("governance_state","")
    action          = req.get("action","")
    agent_id        = req.get("agent_id","")
    context_id      = req.get("context_id","")

    if governance_state not in VGC_STATE_CODES:
        raise HTTPException(status_code=400,
            detail=f"governance_state must be one of: {list(VGC_STATE_CODES.keys())}")

    # Retrieve connected artifacts
    passport = _ISSUED_PASSPORTS.get(passport_id,{})
    receipt  = _GOVERNANCE_ACTION_RECEIPTS.get(receipt_id,{})
    vga      = _VGA_REGISTRY.get(vga_id,{})

    # Compute event hash for identifier
    event_canonical = _canonical_semantic_json({
        "passport_id":      passport_id,
        "receipt_id":       receipt_id,
        "governance_state": governance_state,
        "action":           action,
        "agent_id":         agent_id,
        "timestamp":        ts,
    })
    event_hash = hashlib.sha256(event_canonical.encode()).hexdigest()

    # Build the VGC identifier
    vgc_identifier = _build_vgc_identifier(governance_state, event_hash, ts)
    vgc_id         = f"VGCR-{event_hash[:12].upper()}"  # internal registry ID

    # Evidence root — binding all artifacts
    evidence_root = hashlib.sha256(
        (passport.get("artifact_hash","") +
         receipt.get("receipt_hash","") +
         vga.get("vga_hash","")).encode()
    ).hexdigest()

    vgc = {
        "schema":              VGC_PROTOCOL_VERSION,
        "vgc_id":              vgc_id,

        # THE PRIMITIVE — this is what travels with the AI action
        "vgc_identifier":      vgc_identifier,
        "identifier_format":   "VGC:VS1-{HASH12}-{STATE_CODE}-{DATE8}",

        # Transport representations (carry VGC in any layer)
        "transport": {
            "qr_content":      vgc_identifier,
            "http_header":     f"X-VeriSigil-Governance: {vgc_identifier}",
            "json_field":      {"verisigil_governance": vgc_identifier},
            "uri":             f"https://verify.verisigil.ai/vgc/{vgc_id}",
            "datamatrix":      vgc_identifier,
            "note":            "VGC can be placed in any transport layer without modification",
        },

        # Governance state (canonical five-state)
        "governance_state":    governance_state,
        "governance_label":    CANONICAL_GOVERNANCE_STATES.get(governance_state,{}).get("label",""),
        "state_code":          VGC_STATE_CODES[governance_state],

        # What this governed event is
        "action":              action,
        "agent_id":            agent_id,
        "context_id":          context_id,
        "VALID_AT_TIME":       ts,

        # Evidence artifacts (VGC is the identifier — these are the evidence)
        "artifacts": {
            "passport_id":     passport_id,
            "receipt_id":      receipt_id,
            "vga_id":          vga_id,
            "evidence_root":   evidence_root,
        },

        # Consequence boundary (MANDATORY — from VGA/Passport)
        "consequence_boundary": {
            "permitted":       vga.get("purpose_binding",{}).get("permitted_consequences",[]) or
                               receipt.get("consequence_boundary",{}).get("permitted",[]) or
                               req.get("permitted_consequences",[]),
            "prohibited":      vga.get("purpose_binding",{}).get("prohibited_consequences",[]) or
                               receipt.get("consequence_boundary",{}).get("prohibited",[]) or
                               req.get("prohibited_consequences",[]),
        },

        # Lifecycle
        "lifecycle_status":    "ACTIVE",
        "issued_at":           ts,
        "effective_until":     req.get("effective_until",None),
        "superseded_by":       None,

        # Issuer — always VeriSigilAI
        "issuer": {
            "name":            "VeriSigil AI",
            "identifier":      "verisigilai.com",
            "public_key":      "lJWG0Wabt6uATPu5Upo6UEHWGXQqMyi6LMKQC0xwpY8=",
            "algorithm":       "Ed25519",
            "rule":            "Issuer is always VeriSigilAI. Never obscured. Customer is Subject only.",
        },

        # Verification
        "verification": {
            "online":          f"GET /v1/vgc/resolve/{vgc_id}",
            "offline":         "Verify Ed25519 vgc_signature against public key. Recompute vgc_hash from canonical_json.",
            "no_server_required": True,
            "ivt_tests":       list(VGC_CONFORMANCE_REQUIREMENTS.keys()),
        },

        # C2PA interoperability
        "c2pa_interoperability": {
            "c2pa_role":       "Content provenance (where did this content come from?)",
            "vgc_role":        "Governance provenance (under what authority and conditions did this AI action occur?)",
            "relationship":    "Complementary — VGC does NOT replace C2PA",
            "coexistence":     "A single AI output may carry both a C2PA Content Credential and a VGC",
        },

        # Non-claims (MANDATORY)
        "non_claims": [
            "VGC is an identifier — not the evidence itself",
            "GOVERNED state does NOT mean AI was correct, safe, or universally authorized",
            "VGC does NOT certify regulatory compliance",
            "VGC does NOT replace C2PA content provenance",
            "VGC is NOT a trust score or safety badge",
            "Resolving a VGC requires trusting VeriSigil's resolver — offline verification avoids this",
        ],

        "offline_verifiable":  True,
        "canonical_json":      event_canonical,
    }

    # Cryptographic binding
    vgc["vgc_hash"]          = hashlib.sha256(event_canonical.encode()).hexdigest()
    vgc["vgc_signature"]     = sign_governance_payload(
        {"vgc_id": vgc_id, "vgc_identifier": vgc_identifier,
         "governance_state": governance_state, "evidence_root": evidence_root, "timestamp": ts}
    )

    _VGC_REGISTRY[vgc_id] = vgc
    _emit_proof_event("VGC_ISSUED", vgc_id,
                      {"vgc_identifier": vgc_identifier, "governance_state": governance_state}, ts)

    return vgc


@app.get("/v1/vgc/resolve/{vgc_id}", tags=["VGC — VeriSigil Governance Code"])
async def vgc_resolve(
    vgc_id: str,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    VGC Resolver — resolve a VGC identifier to its governance evidence.

    This is the resolver layer — analogous to GS1 Digital Link
    connecting a product identifier to its information services.

    Resolving a VGC returns:
    - Current governance state
    - Lifecycle status
    - Artifact references (Passport, Receipt, VGA)
    - Verification instructions
    - Current evidence summary

    IMPORTANT: Resolving requires server access.
    For trust-free verification, use offline procedure instead.
    """
    require_api_key(x_api_key, authorization)
    ts  = datetime.now(timezone.utc).isoformat()
    vgc = _VGC_REGISTRY.get(vgc_id)
    if not vgc:
        raise HTTPException(status_code=404, detail=f"VGC {vgc_id} not found")

    passport_id = vgc.get("artifacts",{}).get("passport_id","")
    passport    = _ISSUED_PASSPORTS.get(passport_id,{})

    return {
        "schema":              "VGC-RESOLUTION-v0.1",
        "vgc_id":              vgc_id,
        "vgc_identifier":      vgc.get("vgc_identifier",""),
        "resolved_at":         ts,

        # Current state (may differ from issuance if superseded/revoked)
        "current_governance_state": vgc.get("governance_state",""),
        "lifecycle_status":    vgc.get("lifecycle_status",""),

        # Artifacts
        "artifacts":           vgc.get("artifacts",{}),
        "passport_status":     passport.get("status",""),

        # Consequence boundary (critical for verification)
        "consequence_boundary":vgc.get("consequence_boundary",{}),

        # Verification
        "vgc_signature":       vgc.get("vgc_signature",""),
        "vgc_hash":            vgc.get("vgc_hash",""),
        "public_key":          "lJWG0Wabt6uATPu5Upo6UEHWGXQqMyi6LMKQC0xwpY8=",
        "offline_verification":vgc.get("verification",{}),

        # Non-claims (always present in resolution response)
        "non_claims":          vgc.get("non_claims",[]),

        "resolver_note": (
            "This resolution was served by VeriSigil. For trust-free verification, "
            "use the offline procedure: verify vgc_signature against the published "
            "public key using Ed25519. No server access required."
        ),
    }


@app.get("/v1/vgc/{vgc_id}", tags=["VGC — VeriSigil Governance Code"])
async def vgc_get(
    vgc_id: str,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """Retrieve the full VGC record."""
    require_api_key(x_api_key, authorization)
