# ── StateOracle from vcb_v2_2_final.py ─────────────────────
# (Section 136 — State Oracle Integrity)
VCB_STATE_LEVELS = {
    "AUTHORITATIVE": 3,
    "QUALIFIED":     2,
    "UNVERIFIED":    1,
    "MISSING":       0,
    "CONFLICTING":  -1,
}

def _vcb_state_oracle_assess(
    state,
    source: str,
    freshness_seconds: int = 60,
    observed_at: str = "",
    now_str: str = "",
) -> dict:
    """
    StateOracle — classifies authority/quality of state evidence.
    Section 136 of VCB Architecture v1.4.
    VCB cannot prove governance better than the state supplied to it.
    """
    failures = []
    if state is None:
        failures.append("STATE_MISSING")
    if source not in VCB_STATE_LEVELS:
        failures.append("STATE_SOURCE_UNKNOWN")
    if source == "CONFLICTING":
        failures.append("STATE_CONFLICTING")
    if observed_at:
        try:
            from datetime import datetime as dt
            now = dt.fromisoformat(now_str.replace("Z","+00:00")) if now_str else dt.now(timezone.utc)
            age = (now - dt.fromisoformat(observed_at.replace("Z","+00:00"))).total_seconds()
            if age > freshness_seconds:
                failures.append("STATE_STALE")
        except Exception:
            failures.append("STATE_TIME_INVALID")

    # Requires at least QUALIFIED (level 2) to pass
    status = ("PASS" if not failures and VCB_STATE_LEVELS.get(source, 0) >= 2
              else "NOT_PROVABLE")
    return {
        "status":     status,
        "source":     source,
        "failures":   failures,
        "state_hash": hashlib.sha256(
            json.dumps(state, sort_keys=True, default=str).encode()
        ).hexdigest() if state is not None else None,
    }


