# ── Evidence Custody (Section 126) ─────────────────────────
def _vcb_evidence_custody_record(
    evidence_id: str,
    created_by: str,
    content_hash: str,
    previous_hash: str = "",
    witness: str = "",
) -> dict:
    """Evidence custody metadata — Section 126."""
    ts = datetime.now(timezone.utc).isoformat()
    record = {
        "evidence_id":     evidence_id,
        "created_by":      created_by,
        "created_at":      ts,
        "content_hash":    content_hash,
        "previous_hash":   previous_hash,
        "witness":         witness,
        "custody_transfer":ts,
        "verification_events": [],
    }
    record["custody_hash"] = hashlib.sha256(
        json.dumps({k: v for k, v in record.items() if k != "custody_hash"},
                   sort_keys=True, default=str).encode()
    ).hexdigest()
    return record


