@app.post("/v1/vcb/state-oracle", tags=["VCB Architecture v1.4 — Summary"])
async def vcb_state_oracle(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    StateOracle — classifies authority and quality of state evidence (Section 136).

    VCB cannot prove governance better than the state supplied to it.
    Every critical state input must carry: source, freshness, timestamp,
    hash, authority, verification status.

    VCB distinguishes:
    STATE_PROVIDED → STATE_ATTESTED → STATE_AUTHORITATIVE

    Sources: AUTHORITATIVE | QUALIFIED | UNVERIFIED | MISSING | CONFLICTING
    AUTHORITATIVE (3) or QUALIFIED (2) → PASS
    UNVERIFIED (1) or below → NOT_PROVABLE
    """
    require_api_key(x_api_key, authorization)
    result = _vcb_state_oracle_assess(
        state            = req.get("state"),
        source           = req.get("source","UNVERIFIED"),
        freshness_seconds= int(req.get("freshness_seconds", 60)),
        observed_at      = req.get("observed_at",""),
        now_str          = req.get("now",""),
    )
    result["schema"]   = "VGS-VCB-STATE-ORACLE-1.4"
    result["levels"]   = VCB_STATE_LEVELS
    result["checked_at"] = datetime.now(timezone.utc).isoformat()
    return result


