_PROOF_RUN_RECORDS: list = []


@app.get("/v1/proof-run/1/spec", tags=["Proof Run 1"])
async def proof_run_1_spec():
    """
    PROOF_RUN_1 specification — next milestone is execution, not code.

    Expert: "One real successful proof run is worth more than
             another 50,000 lines of code."

    14-step complete proof transaction sequence.
    No auth required.
    """
    return {**PROOF_RUN_1_SPEC, "timestamp": datetime.now(timezone.utc).isoformat()}


@app.post("/v1/proof-run/1/execute", tags=["Proof Run 1"])
async def proof_run_1_execute(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    Execute PROOF_RUN_1 — all 14 steps against the reference implementation.

    Gate 3 (real actuator) required for step 7-9.
    Current: reference actuator for steps 7-9.
    Result: test evidence, not claims.
    """
    require_api_key(x_api_key, authorization)
    ts       = datetime.now(timezone.utc).isoformat()
    run_id   = f"PR1-{_vcc_hash(ts)[:12].upper()}"
    results  = {}
    failures = []

    # Step 1: Proposal
    proposal = req.get("proposal") or {
        "type": "payment_destination_change",
        "purpose": "supplier_payment",
        "beneficiary": "SUPPLIER-001",
        "amount": 50000,
        "currency": "USD",
        "account_id": "ACC-SUPPLIER-001",
    }
    results["step_1_proposal"] = {"status": "RECEIVED", "proposal": proposal}

    # Step 2: Authority
    authority = req.get("authority") or {
        "status": "ACTIVE",
        "subject": "agent-finance-001",
        "scope": ["payment_destination_change"],
        "issued_at": ts,
        "valid_until": "2026-12-31T00:00:00Z",
    }
    auth_ok = authority.get("status") == "ACTIVE" and "payment_destination_change" in (authority.get("scope") or [])
    results["step_2_authority"] = {"status": "VERIFIED" if auth_ok else "FAILED", "authority": authority}
    if not auth_ok:
        failures.append("AUTHORITY_INVALID")

    # Step 3: Material commitment
    mc = build_material_commitment_v2(
        purpose=proposal.get("purpose",""), beneficiary=proposal.get("beneficiary",""),
        amount=proposal.get("amount",0), currency=proposal.get("currency",""),
        scope="PAYMENT_DESTINATION",
    )
    results["step_3_material_commitment"] = {"status": "BUILT", "fingerprint": mc["commitment_fingerprint"][:16]}

    # Step 4: VCB decision
    auth_hash  = _vcc_hash(authority)
    state      = req.get("current_state") or {"account_status": "ACTIVE", "balance": 500000}
    state_hash = _vcc_hash(state)
    policy     = req.get("policy") or {"version": "1.0", "max_amount": 100000}
    policy_hash= _vcc_hash(policy)
    action_hash= _vcc_hash(proposal)

    constraint_fail = float(proposal.get("amount",0)) > float(policy.get("max_amount",100000))
    vcb_decision = "DENY" if (not auth_ok or constraint_fail) else "ALLOW"
    decision_hash = _vcc_hash({"decision": vcb_decision, "action_hash": action_hash, "ts": ts})
    vcb_record = {
        "decision": vcb_decision, "decision_hash": decision_hash,
        "failures": (["AUTHORITY_INVALID"] if not auth_ok else []) + (["MAX_AMOUNT_EXCEEDED"] if constraint_fail else []),
        "evaluated_at": ts,
    }
    vcb_record["governance_signature"] = sign_governance_payload({"decision_hash": decision_hash})
    results["step_4_vcb_decision"] = {"status": vcb_decision, "record": vcb_record}
    if vcb_decision == "DENY":
        failures.append("VCB_DENIED")

    # Step 5: Commit-time requalification
    requalif = {
        "action_hash": action_hash, "authority_hash": auth_hash,
        "state_hash": state_hash, "policy_hash": policy_hash,
        "requalified_at": ts, "result": "PASS" if not failures else "FAIL",
    }
    results["step_5_requalification"] = {"status": requalif["result"], "record": requalif}

    if not failures:
        # Step 6: VCC issuance
        vcc = issue_vcc_safe(
            vcb_decision_id=run_id, action_payload=proposal,
            consequence_type="PAYMENT.DESTINATION_CHANGE",
            material_bounds={"amount":proposal.get("amount",0),"currency":proposal.get("currency","")},
            material_commitment=mc, authority_hash=auth_hash,
            policy_hash=policy_hash, state_hash=state_hash,
            requalification_at=ts, enforcement_point="payment-actuator-v1",
            ttl_seconds=300,
        )
        results["step_6_vcc"] = {"status": "ISSUED", "vcc_id": vcc.get("vcc_id"), "vcc": vcc}

        # Step 7-8: Actuator enforcement
        enforcement = _actuator_execute_payment(vcc=vcc, destination_change=proposal)
        results["step_7_8_actuator"] = {
            "status": "ACCEPTED" if enforcement.get("accepted") else "REJECTED",
            "note": "Reference actuator — Gate 3 (real actuator) required for production proof",
            "evidence": enforcement,
        }

        # Step 9: Consequence observation
        results["step_9_consequence"] = {
            "status": "CONSEQUENCE_NOT_OBSERVED",
            "note": "Reference actuator cannot confirm real-world state change. Authoritative external confirmation required.",
        }

        # Step 10: Evidence Seal (governance signature on VCC)
        results["step_10_evidence_seal"] = {
            "status": "SEALED",
            "signature": vcc.get("issuer_signature","")[:32] + "...",
            "public_key": "lJWG0Wabt6uATPu5Upo6UEHWGXQqMyi6LMKQC0xwpY8=",
        }

        # Step 11: Proof Passport
        passport = build_proof_passport(
            vcc=vcc, vcb_decision=vcb_record, material_commitment=mc,
            enforcement_evidence=enforcement,
            consequence_observation=enforcement.get("consequence"),
        )
        results["step_11_proof_passport"] = {"status": "BUILT", "passport_id": passport.get("passport_id")}

        # Step 12: Offline verification
        indep = verify_vcc_independent(vcc, presented_action=proposal, presented_enforcement_point="payment-actuator-v1")
        results["step_12_offline_verification"] = {"status": indep["result"], "evidence": indep}

        # Step 13: Adversarial replay
        replay = verify_vcc_independent(vcc, presented_action=proposal, presented_enforcement_point="payment-actuator-v1")
        results["step_13_adversarial_replay"] = {
            "status": "PASS" if replay["result"] == "INVALID" else "FAIL",
            "result": replay["result"],
            "expected": "INVALID (consumed)",
        }

        # Step 14: Independent reproduction
        results["step_14_independent_reproduction"] = {
            "status": "PENDING",
            "note": "Gate 7 — requires external party. Alkama Run 4 + Harold OMNIX (NDA-compliant).",
            "verification_spec": "GET /v1/vcc/independent-reproduction-spec",
        }
    else:
        for step in range(6, 15):
            results[f"step_{step}_skipped"] = {"status": "SKIPPED", "reason": f"VCB DENY: {failures}"}
        passport = {}
        vcc = {}

    run_record = {
        "schema":      "VGS-PROOF-RUN-1-RESULT-1.0",
        "run_id":      run_id,
        "steps":       14,
        "results":     results,
        "failures":    failures,
        "overall":     "PARTIAL" if not failures else "DENIED",
        "passed_steps":sum(1 for v in results.values() if isinstance(v,dict) and v.get("status") not in ("SKIPPED","PENDING","CONSEQUENCE_NOT_OBSERVED")),
        "gate_blockers": [
            "Gate 3 PARTIAL — reference actuator only, real actuator required",
            "Gate 7 PENDING — external reproduction required",
        ],
        "next_action":  "Commission Alkama Run 4. Contact Naimatullah/Velos. Harold OMNIX adversarial challenge.",
        "timestamp":    ts,
    }
    _PROOF_RUN_RECORDS.append({"run_id": run_id, "overall": run_record["overall"], "ts": ts})
    return run_record


@app.get("/v1/proof-run/1/history", tags=["Proof Run 1"])
async def proof_run_1_history(
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """History of PROOF_RUN_1 executions."""
    require_api_key(x_api_key, authorization)
    return {"schema": "VGS-PROOF-RUN-HISTORY-1.0", "runs": _PROOF_RUN_RECORDS,
            "total": len(_PROOF_RUN_RECORDS), "timestamp": datetime.now(timezone.utc).isoformat()}





@app.post("/v1/vcb/evaluate", tags=["VCB — Canonical API"])
async def vcb_evaluate_canonical(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    POST /v1/vcb/evaluate — canonical VCB evaluation endpoint (Section 44).
    Uses VCBFinalEngine (Section 54) with 23-step adjudication (Section 55).
    All evaluation dimensions (novelty, predictability, reversibility,
    counterfactual, coherence, consequence envelope) are VCB-internal.
    NOT new engines — structured evidence feeding VCB.
    """
    require_api_key(x_api_key, authorization)
    result = _VCB_FINAL_ENGINE.evaluate(
        action             = req.get("action", {}),
        authority          = req.get("authority", {}),
        state              = req.get("current_state", {}),
        policy             = req.get("policy", {}),
        semantic_commitment= req.get("semantic_commitment"),
        provenance         = req.get("provenance"),
        consequence_type   = req.get("consequence_type", ""),
        bounds             = req.get("bounds", {}),
        session            = req.get("session", {}),
        evidence           = req.get("evidence", []),
        receiver           = req.get("receiver"),
        enforcement_point  = req.get("enforcement_point", ""),
        transition_record  = req.get("transition_record"),
        known_patterns     = req.get("known_patterns"),
    )
    return {"schema": "VGS-VCB-EVALUATE-2.0", **result}



# ─────────────────────────────────────────────────────────────────────────────
# HELPER: build_vcb_decision_object + issue_sigilmark
# Referenced by ~20 endpoints. Defined once here as canonical helpers.
# ─────────────────────────────────────────────────────────────────────────────

def build_vcb_decision_object(
    decision: str,
    action_hash: str,
    consequence_type: str,
    authority_hash: str,
    policy_hash: str,
    state_hash: str,
    enforcement_point: str,
    reason_code: str = "",
    material_bounds: dict = None,
) -> dict:
    """Build a canonical VCB decision object for use with issue_sigilmark."""
    ts = datetime.now(timezone.utc).isoformat()
    return {
        "decision":           decision,
        "decision_id":        f"DEC-{_vcc_hash({'d': decision, 'a': action_hash, 't': ts})[:16].upper()}",
        "action_hash":        action_hash,
        "consequence_type":   consequence_type,
        "authority_hash":     authority_hash,
        "policy_hash":        policy_hash,
        "state_hash":         state_hash,
        "material_bounds":    material_bounds or {},
        "enforcement_point":  enforcement_point,
        "reason_code":        reason_code,
        "timestamp":          ts,
    }


def issue_sigilmark(
    vcb_decision: dict,
    action_payload: dict,
    enforcement_point: str = "",
    ttl_seconds: int = 300,
    material_commitment: dict = None,
    consequence_envelope: dict = None,
    transition_record: dict = None,
    could_field: dict = None,  # P5: Halpern-Pearl COULD conjunct (optional)
) -> dict:
    """Issue a SigilMark portable proof package from a VCB decision object."""
    ts      = datetime.now(timezone.utc).isoformat()
    expires = (datetime.now(timezone.utc) + __import__('datetime').timedelta(seconds=ttl_seconds)).isoformat()
    decision = vcb_decision.get("decision", "UNKNOWN")
    action_hash = vcb_decision.get("action_hash") or _vcc_hash(action_payload)
    nonce   = hashlib.sha256(f"{action_hash}{ts}{enforcement_point}".encode()).hexdigest()[:32]
    sm_id   = f"SM-{_vcc_hash({'a': action_hash, 'n': nonce, 't': ts})[:20].upper()}"

    # Key fingerprint for historical key tracking (Grok/Perplexity/Qwen finding)
    _pub_key_bytes = VERIFY_KEY.encode()
    # Gemini R2 NEW-03: expanded from 16 to 32 hex chars (128-bit fingerprint)
    # Full SHA-256 = 64 hex. 32 hex = 128 bits = adequate collision resistance.
    # 16 hex = 64 bits = birthday bound at ~4B keys (insufficient for multi-key environments)
    _key_id = hashlib.sha256(_pub_key_bytes).hexdigest()[:32]

    # ASCII key contract: SigilMark keys MUST be ASCII-only for JCS equivalence
    # Python sort_keys=True is identical to RFC 8785/JCS for ASCII keys only
    # ChatGPT R2 NEW-F17: ValueError must fail-closed, not leak through exception handlers
    _NON_ASCII_KEYS = [k for k in vcb_decision.keys() if not k.isascii()]
    if _NON_ASCII_KEYS:
        # Return NOT_PROVABLE dict instead of raising — prevents exception propagation
        # into unknown exception handlers that might fail open
        return {
            "schema": "VGS-SIGILMARK-ERROR-1.0",
            "error": "NOT_PROVABLE.NON_ASCII_KEYS",
            "reason": f"SigilMark keys must be ASCII-only for canonical form guarantee",
            "non_ascii_keys": _NON_ASCII_KEYS,
            "release": "REFUSED",
        }

    payload = {
        "schema":                 "VGS-SIGILMARK-2.2",  # Condition record with declared limits — v2.2
        "payload_version":        "2.2",              # One version bump — all v2.2 fields batched
        "terminology_version":    "VGS-TERMINOLOGY-1.0",  # Locks claim language to this passport
        "sigilmark_id":           sm_id,
        "vcb_id":                 sm_id,
        "decision":               decision,
        "action_hash":            action_hash,
        "authority_hash":         vcb_decision.get("authority_hash", ""),
        "policy_hash":            vcb_decision.get("policy_hash", ""),
        "state_hash":             vcb_decision.get("state_hash", ""),
        "consequence_type":       vcb_decision.get("consequence_type", ""),
        "enforcement_point":      enforcement_point,
        "nonce":                  nonce,
        "issued_at":              ts,
        "expires_at":             expires,
        "material_commitment":    material_commitment or {},
        "consequence_envelope":   consequence_envelope or {},
        "transition_record":      transition_record or {},
        "consumption_state":      "NOT_YET_CONSUMED",
        "consumption_state_note": "Signed at issuance — always NOT_YET_CONSUMED in artifact; query DB for current state",
        "build_hash":             _get_full_build_identity().get("sha256_prefix", ""),
        "signing_key_id":         _key_id,
        "signing_algorithm":      "Ed25519",
        "canonical_form":         "compact-json-sha256-v1",
        "reconciliation": {
            # RECONCILIATION: compare authorized transition to observed consequence
            # Expert: "without reconciliation, you can prove what VCB believed should happen.
            # With reconciliation, you can investigate what actually happened."
            "schema": "VGS-RECONCILIATION-1.0",
            "authorized_action_hash": action_hash,
            "expected_consequence_type": vcb_decision.get("consequence_type", ""),
            "observed_consequence": None,  # Populated after actuator execution (P4)
            "reconciliation_result": "NOT_YET_RECONCILABLE",  # MATCH | MISMATCH | NOT_RECONCILABLE
            "node_id": f"RECONCILIATION-{action_hash[:16]}",
            "implementation_status": "NOT_IMPLEMENTED — requires real actuator (P4)",
        },
        "claim_limitations": [
            "STILL: authority continuity at commitment NOT YET ENFORCED (R003 SPEC_ONLY)",
            "COULD: boundary leverage NOT YET ENFORCED (no real actuator)",
            "WHAT: execution evidence NOT YET AVAILABLE (no real actuator)",
            "CONSUMPTION_STATE: always NOT_YET_CONSUMED in signed artifact; query DB for current state",
            "MULTI_INSTANCE: distributed atomicity demonstrated single-instance only",
        ],
        "evidence_freshness": {
            "checked_at":                  ts,
            "authority_fresh_until":       None,  # Populated when STILL adapter queries authority
            "evidence_currency":           "NOT_PROVABLE",  # R004: SPEC_ONLY until STILL fully enforced
            "freshness_note":              "Expert §14: freshness is a first-class property.",
            "freshness_window_seconds":    30,  # HIGH consequence (payment domain)
            # P3.2 / STILL interval fields — required for offline STILL verification (INV-PCA-01)
            # Reviewer: "OCSP relying parties check freshness against a signed past instant"
            # These fields allow jar_verify to verify STILL arithmetic offline without re-querying
            "decision_binding_at":         ts,           # T0: when the authority was declared
            "source_known_correct_at":     ts,           # Last confirmed authority state
            "next_information_expected":   None,         # T1: when STILL recheck is due (set by STILL adapter)
            "observed_staleness_ms":       0,            # Measured T1-T0 staleness at verification time
            "evaluation_mode":             "HASH_CONTINUITY",  # HASH_CONTINUITY | SUPABASE_QUERY | NOT_ESTABLISHED
            "still_interval_schema":       "VGS-STILL-INTERVAL-1.0",
            "status":                       "UNKNOWN",   # Set to PROVABLE when hash continuity confirmed
            "result":                       "NOT_PROVABLE",  # Set by STILL adapter
            "max_staleness_ms":             30000,       # 30s for HIGH consequence domain
            # INV-AUTH-TEMP-01: Temporal validity distinction
            # VALID_AT_RELEVANT_TIME: was the authority valid when the action was examined?
            # CURRENTLY_VALID: is the authority valid right now?
            # These are SEPARATE claims and must never be collapsed.
            "valid_at_relevant_time":       True,        # Authority was valid at decision_binding_at
            "currently_valid":              "UNKNOWN",   # Must be determined by STILL adapter at T1
            "temporal_validity_note": (
                "VALID_AT_RELEVANT_TIME ≠ CURRENTLY_VALID. "
                "Historical passports remain verifiable even after authority has changed. "
                "INV-AUTH-TEMP-01: accountability evidence must survive authority."
            ),
        },
        "t0_baseline": {
            # T0 authority snapshot — captured at examination time
            # This is what STILL revalidation compares against at T1
            "schema": "VGS-T0-BASELINE-1.0",
            "authority_id": vcb_decision.get("authority_hash", ""),
            "authority_version": vcb_decision.get("authority_version", "v1"),
            "authority_source": vcb_decision.get("authority_source", "NOT_SPECIFIED"),
            "scope_hash": vcb_decision.get("state_hash", ""),
            "conditions_hash": _vcc_hash({
                "policy": vcb_decision.get("policy_hash",""),
                "state": vcb_decision.get("state_hash",""),
            }),
            "baseline_captured_at": ts,
            "node_id": f"T0-{vcb_decision.get('authority_hash','x')[:16]}",
            "implementation_note": (
                "P3.2: treasury_mandate_id must be passed via vcb_decision.authority_id "
                "to enable STILL revalidation at commitment time."
            ),
            # INV-COMMIT-01: policy commitment verification
            # The policy_hash declared here must match the policy used at evaluation.
            # An independent verifier can check: hash(loaded_policy) == policy_hash
            # If they differ, the evaluation used a different policy than declared.
            "policy_commitment_verification": {
                "schema":      "VGS-POLICY-COMMITMENT-1.0",
                "policy_hash": vcb_decision.get("policy_hash", "NOT_DECLARED"),
                "state_hash":  vcb_decision.get("state_hash", "NOT_DECLARED"),
                "commitment_rule": (
                    "hash(loaded_policy) MUST EQUAL policy_hash at evaluation time. "
                    "If not equal: REJECT. INV-COMMIT-01."
                ),
                "verified_at": ts,
            },
        },
        "canonical_form": "rfc8785-jcs-v1",  # Updated from compact-json-sha256-v1
        "why_examination": {
            # P1: PROV-DM vocabulary — W3C Recommendation 30 April 2013
            # Closed enum — VCB_JAR_GRAMMAR_v1.why_edges_rel_enum
            "examination_schema": "VGS-WHY-EXAMINATION-2.0",
            # INV-SUFF-01/02/03: Evidentiary sufficiency is separate from provenance/integrity
            "evidentiary_sufficiency": {
                "schema":                "VGS-EVIDENTIARY-THRESHOLD-1.0",
                "consequence_class":     vcb_decision.get("consequence_type", "UNSPECIFIED"),
                "threshold_id":          vcb_decision.get("policy_hash", "")[:16] if vcb_decision.get("policy_hash") else "NOT_DECLARED",
                "threshold_version":     vcb_decision.get("authority_version", "v1"),
                "declared_by":           vcb_decision.get("authority_hash", ""),
                "sufficiency_result":    "NOT_PROVABLE",  # Default: declared threshold not yet examined
                "sufficiency_note": (
                    "INV-SUFF-01: provenance/integrity do not establish consequential sufficiency. "
                    "INV-SUFF-02: threshold must be attributable to declared authority. "
                    "Sufficiency examination requires explicit evidence_requirement_profile at commit time."
                ),
            },
            "requirement_id":     vcb_decision.get("consequence_type", "UNSPECIFIED"),
            "authority_reference": vcb_decision.get("authority_hash", ""),
            "admissible_region_reference": _vcc_hash({
                "authority": vcb_decision.get("authority_hash",""),
                "policy": vcb_decision.get("policy_hash",""),
                "consequence_type": vcb_decision.get("consequence_type",""),
            }),
            "identity_continuity": {
                # INV-ID-01: identity ≠ authority
                # INV-ID-02: authority must bind to the relevant subject
                # INV-ID-03: runtime discontinuity must not inherit consequence rights
                "schema":              "VGS-IDENTITY-CONTINUITY-1.0",
                "subject_id":          vcb_decision.get("subject_id", "NOT_DECLARED"),
                "subject_type":        vcb_decision.get("subject_type", "UNKNOWN"),
                "issuer_or_source":    vcb_decision.get("authority_hash", "NOT_DECLARED"),
                "runtime_binding":     "AT_ISSUE_TIME",  # Revalidated at T1 by STILL + identity continuity
                "evidence_status":     "CURRENT",        # Status at T0; STILL checks T1
                "continuity_result":   "NOT_PROVABLE",   # Default: requires live STILL to establish
                "note": (
                    "Identity continuity must be re-examined at commitment time. "
                    "This field records T0 state only. "
                    "INV-ID-03: runtime discontinuity must not inherit consequence rights."
                ),
            },
            "evidentiary_sufficiency": {
                # INV-SUFF-01: provenance/integrity ≠ sufficiency for this consequence
                # INV-SUFF-02: threshold must be declared by authority, not invented here
                # INV-SUFF-03: INSUFFICIENT ≠ NOT_PROVABLE
                "schema":            "VGS-EVIDENTIARY-SUFFICIENCY-1.0",
                "consequence_class": vcb_decision.get("consequence_type", "UNSPECIFIED"),
                "threshold_id":      vcb_decision.get("threshold_id", "NOT_DECLARED"),
                "declared_by":       vcb_decision.get("authority_hash", "NOT_DECLARED"),
                "sufficiency_result": (
                    "NOT_PROVABLE"  # Default: threshold must be declared before sufficiency can be examined
                    if not vcb_decision.get("threshold_id")
                    else "DECLARED_PENDING_EXAMINATION"
                ),
                "note": (
                    "Provenance, integrity, and policy validity do not by themselves "
                    "establish evidentiary sufficiency for this consequence class. "
                    "INV-SUFF-01: positive evidence result ≠ sufficiency for higher consequence."
                ),
            },
            "action_examined":    action_hash,
            "enforcement_point":  enforcement_point,
            "evaluation_result":  decision,
            "examined_at":        ts,
            "why_edges": [
                {"rel": "GENERATED_BY",         "entity": action_hash,                                  "note": "governed output produced by this action"},
                {"rel": "ATTRIBUTED_TO",        "entity": vcb_decision.get("authority_hash", ""),       "note": "responsible agent/authority"},
                {"rel": "ASSOCIATED_WITH_PLAN", "entity": vcb_decision.get("policy_hash", ""),          "note": "policy executed under"},
                {"rel": "USED",                 "entity": vcb_decision.get("state_hash", ""),           "note": "state consumed at examination"},
                {"rel": "ACTED_ON_BEHALF_OF",   "entity": vcb_decision.get("authority_hash", ""),       "note": "upstream principal — delegation edge"},
            ],
            "evidence_references": {
                "action_hash":    action_hash,
                "authority_hash": vcb_decision.get("authority_hash", ""),
                "policy_hash":    vcb_decision.get("policy_hash", ""),
                "state_hash":     vcb_decision.get("state_hash", ""),
            },
            "reconstruction_possible": True,
            "node_id": f"WHY-{action_hash[:16]}",
            "positive_semantics": (
                "WHY=ADMISSIBLE asserts: an authority chain and policy were present at examined_at. "
                "It does not assert that the authority remained valid at commitment, that the action "
                "was prevented from causing harm, or that no unmodelled execution path existed."
            ),
        },
        "closure": {
            "schema":        "VGS-CLOSURE-1.0",
            "limit":         3,
            "depth_reached": 1,
            "terminated":    "AT_DECLARED_ROOT",
            "truncation_code": None,
            "root": {
                "kind":    "ORGANIZATIONAL_FIAT",
                "ref":     vcb_decision.get("authority_hash", "UNSPECIFIED"),
                "provable": False,
            },
        },
        "assurance": {
            "schema":             "VGS-ASSURANCE-TRIPLE-1.0",
            "integrity_class":    "SELF_REPORTED",
            "custody_class":      "GAP_UNKNOWN",
            # INV-EV-03: independence_class computed from dependency_sets, never asserted
            # If dependency_sets absent or overlap found => NOT_ESTABLISHED
            # Checker computes this — caller cannot assert INDEPENDENT
            "independence_class": "NOT_ESTABLISHED",  # Computed below from dependency_sets
            "dependency_sets": {
                # Each conjunct declares its dependencies
                # If any two conjuncts share a dependency: SHARED_DEPENDENCY
                # If dependency_sets absent: NOT_ESTABLISHED (never INDEPENDENT)
                "WHY": ["policy_hash", "authority_hash", "action_hash"],
                "STILL": ["authority_hash"],
                "COULD": [],   # NOT_MODELLED — no causal model yet
                "WHAT": [],    # NOT_IMPLEMENTED — no real actuator
            },
        },
        # P3: Custody chain with digest continuity (INV-EV-04)
        "custody": [
            {
                "handler_id":    "VCB-EXAMINER-1.0",
                "action":        "COLLECT",
                "at":            ts,
                "digest_before": _vcc_hash(action_payload) if action_payload else "",
                "digest_after":  action_hash,
                "tool_id":       "VCB-CANONICAL-HASHER",
                "tool_version":  "rfc8785-jcs-v1",
            },
            {
                "handler_id":    "VCB-EXAMINER-1.0",
                "action":        "STORE",
                "at":            ts,
                "digest_before": action_hash,
                "digest_after":  "PENDING_INTEGRITY_HASH",  # Updated after hash computed
                "tool_id":       "VCB-SIGILMARK-ISSUER",
                "tool_version":  "VCB-2.2",
            },
        ],
        "replay": {
            "schema":                        "VGS-REPLAY-DIGESTS-1.0",
            "policy_digest":                 vcb_decision.get("policy_hash", ""),
            "input_digest":                  action_hash,
            "entity_snapshot_digest":        vcb_decision.get("state_hash", ""),
            "engine_version":                "VCB-2.2",
            "evaluation_order_independent":  True,
            "status":                        "REPLAY_AVAILABLE",
        },
        "scope_ledger": {
            "schema": "VGS-SCOPE-LEDGER-1.0",
            "required_line": "a scope ledger enumerates known limits and is not an exhaustive list of everything unproven",
            "limits": [
                {"code": "UPSTREAM_PRINCIPAL_UNRESOLVED",    "note": "chain stops at treasury mandate root"},
                {"code": "INDEPENDENCE_NOT_ESTABLISHED",     "note": "dependency sets not declared — P3"},
                {"code": "ALTERNATIVES_NOT_MODELLED",        "note": "counterfactual alternatives not modelled — beyond P5 single-domain scope"},
                *([] if could_field and could_field.get("result") == "ACTUAL_CAUSE" else
                  [{"code": "INTERVENTION_WINDOW_NOT_MODELLED", "note": "COULD window not measured — provide could_field for P5"}]),
                {"code": "STILL_HASH_CONTINUITY_ONLY", "note": "STILL uses hash continuity; full revocation check requires Supabase connection"},
            ],
        },
        # P5: COULD conjunct — Halpern-Pearl causal model (payment domain)
        # could_field is provided by the endpoint that calls evaluate_release + actuator
        # For /v1/vcb/seal: could_field is None (caller has no actuator)
        # For /v1/p5/seal: could_field is computed by _compute_could_field()
        "could": could_field,  # None = NOT_MODELLED (correct); dict = P5 COULD conjunct
    }
    # Perplexity R2-02: domain_prefix must be INSIDE integrity hash
    # All trust-critical metadata (domain_prefix, signing_key_id, canonical_form)
    # must be integrity-protected — RFC 7515 §6 requirement
    payload["domain_prefix"] = "SIGILMARK-v1"  # included INSIDE integrity hash
    # Kimi R2 KC-05: domain_prefix exclusion must be documented in external material
    # This field IS inside the integrity hash (set before _vcc_hash computed)
    # Verifiers must use hardcoded prefix b"SIGILMARK-v1\x00", not this field value
    # See domain_prefix_note field in issued passport for consumer guidance

    # P3: Compute independence_class from dependency_sets — INV-EV-03
    # Computed in code, never asserted. Checker verifies this computation.
    _p3_dep = payload.get("assurance", {}).get("dependency_sets", {})
    if _p3_dep:
        _p3_active = [set(v) for v in _p3_dep.values() if v]
        if len(_p3_active) >= 2:
            _p3_shared = False
            for _p3_i, _p3_s1 in enumerate(_p3_active):
                for _p3_s2 in _p3_active[_p3_i+1:]:
                    if _p3_s1 & _p3_s2:
                        _p3_shared = True
                        break
                if _p3_shared:
                    break
            payload["assurance"]["independence_class"] = "SHARED_DEPENDENCY" if _p3_shared else "INDEPENDENT"
        else:
            payload["assurance"]["independence_class"] = "NOT_ESTABLISHED"


    # Compute integrity hash — convert to JSON-safe form first
    # CRITICAL: jar_verify reads the JSON response. We must hash exactly
    # what jar_verify will see after JSON serialization.
    # FastAPI serializes datetime → str, None → null, etc.
    # We must apply the same transformation before hashing.
    _json_safe = json.loads(json.dumps(
        {k: v for k, v in payload.items() if k not in ("integrity_hash", "signature")},
        default=str
    ))
    payload["integrity_hash"] = _vcc_hash(_json_safe)

    # P3: Update custody STORE digest_after with actual integrity_hash
    if "custody" in payload:
        for _entry in payload["custody"]:
            if _entry.get("digest_after") == "PENDING_INTEGRITY_HASH":
                _entry["digest_after"] = payload["integrity_hash"]


    # P3: Recompute integrity_hash after custody update (custody now has actual hash)
    # This ensures verify_sigilmark sees consistent custody digest
    if "custody" in payload:
        _json_safe = json.loads(json.dumps(
            {k: v for k, v in payload.items() if k not in ("integrity_hash", "signature")},
            default=str
        ))
        payload["integrity_hash"] = _vcc_hash(_json_safe)

    # Domain-separated signing over full payload (excluding signature only)
    # Sign the JSON-safe version for the same reason
    domain_bytes = b"SIGILMARK-v1" + b"\x00"  # no literal null in source
    _sig_payload_safe = json.loads(json.dumps(
        {k: v for k, v in payload.items() if k != "signature"},
        default=str
    ))
    payload_bytes = domain_bytes + _vcb_canonical(_sig_payload_safe)
    raw_sig = SIGNING_KEY.sign(payload_bytes).signature
    payload["signature"] = base64.b64encode(raw_sig).decode()
    return payload


