# ═══════════════════════════════════════════════════════════════════════════════
# STILL AUTHORITY SOURCE ADAPTER
# ADR-014 §13 — SP-1: STILL must be obtained inside the gate from the authority source.
# The gate must not accept a caller-supplied still_result as the sole basis.
# ═══════════════════════════════════════════════════════════════════════════════

async def still_authority_source_adapter(
    authority_id: str,
    proposed_amount: float = 0.0,
    proposed_vendor: str = "",
    t0_baseline_hash: str = "",
) -> dict:
    """
    Domain-specific STILL authority source adapter.
    ADR-014 §13: Treasury action → Treasury Authority Adapter.

    Independently establishes whether the required authority conditions
    still hold at commitment time. The result is NOT supplied by the caller —
    it is derived from the authority source (Supabase treasury_mandates).

    Three outcomes (ADR-014 §14):
    - STILL_PROVABLE: required current conditions established
    - STILL_FAILED: conditions established and no longer satisfied
    - STILL_NOT_PROVABLE: cannot establish whether conditions remain satisfied

    Critical property: source unavailable → STILL_NOT_PROVABLE → no release.
    Never: source unavailable → assume STILL_PROVABLE → release.
    """
    ts = datetime.now(timezone.utc).isoformat()

    if not authority_id:
        return {
            "result": "STILL_NOT_PROVABLE",
            "reason": "NO_AUTHORITY_ID",
            "ts": ts,
            "source": "TREASURY_AUTHORITY_ADAPTER",
        }

    # Query the authority source directly — never use caller-supplied value
    try:
        mandate = await query_authority_at_t1(authority_id)
    except Exception as e:
        # Source unavailable → STILL_NOT_PROVABLE → no release
        return {
            "result": "STILL_NOT_PROVABLE",
            "reason": "AUTHORITY_SOURCE_UNAVAILABLE",
            "error": str(e)[:100],
            "ts": ts,
            "source": "TREASURY_AUTHORITY_ADAPTER",
            "adr014_rule": "Source unavailable reduces what can be admitted, never increases it",
        }

    if not mandate:
        return {
            "result": "STILL_NOT_PROVABLE",
            "reason": "AUTHORITY_NOT_FOUND",
            "authority_id": authority_id,
            "ts": ts,
            "source": "TREASURY_AUTHORITY_ADAPTER",
        }

    # Check revocation
    if mandate.get("status") == "REVOKED":
        return {
            "result": "STILL_FAILED",
            "reason": "STILL_AUTHORITY_REVOKED",
            "authority_id": authority_id,
            "revoked_at": mandate.get("revoked_at"),
            "ts": ts,
            "source": "TREASURY_AUTHORITY_ADAPTER",
        }

    # Check expiry
    expiry = mandate.get("valid_until")
    if expiry:
        try:
            from dateutil.parser import parse as _parse
            if datetime.now(timezone.utc) > _parse(expiry):
                return {
                    "result": "STILL_FAILED",
                    "reason": "STILL_AUTHORITY_EXPIRED",
                    "authority_id": authority_id,
                    "expired_at": expiry,
                    "ts": ts,
                    "source": "TREASURY_AUTHORITY_ADAPTER",
                }
        except Exception:
            pass

    # Check amount ceiling
    amount_limit = mandate.get("amount_limit", 0)
    if proposed_amount > amount_limit:
        return {
            "result": "STILL_FAILED",
            "reason": "STILL_CEILING_EXCEEDED",
            "authority_id": authority_id,
            "proposed": proposed_amount,
            "limit": amount_limit,
            "ts": ts,
            "source": "TREASURY_AUTHORITY_ADAPTER",
        }

    # Check vendor authorization
    authorized_vendors = mandate.get("authorized_vendors", [])
    if authorized_vendors and proposed_vendor and proposed_vendor not in authorized_vendors:
        return {
            "result": "STILL_FAILED",
            "reason": "STILL_VENDOR_UNAUTHORIZED",
            "authority_id": authority_id,
            "proposed_vendor": proposed_vendor,
            "authorized_vendors": authorized_vendors,
            "ts": ts,
            "source": "TREASURY_AUTHORITY_ADAPTER",
        }

    # Derive current authority hash and check for material delta
    current_hash = _vcc_hash({
        "mandate_id": authority_id,
        "status": mandate.get("status"),
        "amount_limit": amount_limit,
        "authorized_vendors": authorized_vendors,
    })
    material_delta = (t0_baseline_hash and current_hash != t0_baseline_hash)

    return {
        "result": "STILL_PROVABLE",
        "authority_id": authority_id,
        "current_status": mandate.get("status"),
        "current_hash": current_hash,
        "t0_baseline_hash": t0_baseline_hash,
        "material_delta": material_delta,
        "ts": ts,
        "source": "TREASURY_AUTHORITY_ADAPTER",
        "note": "STILL established by direct authority source query — not caller-supplied",
    }


def evaluate_release(
    examination_result: dict,
    consumption_result: dict = None,
    still_result: str = "NOT_VERIFIED",
    could_result: str = "NOT_VERIFIED",
    # P3.2: authority context for internal STILL query
    authority_id: str = None,
    subject_id: str = None,
    authority_version_at_t0: str = None,
    t0_baseline_hash: str = None,
    proposed_amount: float = None,
    proposed_vendor: str = None,
    enforce_still: bool = True,   # P0: live STILL enforcement — on when authority context provided
) -> dict:
    """
    Single gate for all ALLOW decisions.
    All exceptions produce NOT_PROVABLE → refuse. Never fail-open.
    CRITICAL: Use POSITIVE ALLOWLIST — if not PROVABLE, refuse.
    Never: if not FAILED: allow() — that treats NOT_PROVABLE as success.

    P3.2 enhancement:
      When authority_id is supplied AND enforce_still=True:
        STILL is queried INTERNALLY against treasury_mandate_store.
        Caller cannot inject still_result='PROVABLE' to bypass the check.
        (Qwen R2 finding: still_result as parameter = bypassable)

      When enforce_still=False (current default):
        STILL is logged as NOT_ENFORCED_SPEC_ONLY (honest, not blocking)
    """
    try:
        # Gate 1: WHY — POSITIVE ALLOWLIST (expert §4)
        # Never: if result != FAILED: allow()
        # Always: if why != PROVABLE: refuse()
        # Unknown values, None, empty string, unexpected enums ALL refuse.
        verdict = examination_result.get("verdict") if examination_result else None
        # Strict allowlist — only exact known admissible verdicts pass
        ADMISSIBLE_VERDICTS = frozenset({"ALLOW", "VALID", "ADMISSIBLE"})
        if verdict not in ADMISSIBLE_VERDICTS:
            return {
                "release": "REFUSED",
                "gate_failed": "WHY",
                "primary_code": "GATE_UNDETERMINED",
                "state_mutation": "NONE",
                "vcb_inv": "INV-COMMIT-02",
                "reason": f"Examination verdict not in admissible set: {repr(verdict)}",
                "admissible_verdicts": list(ADMISSIBLE_VERDICTS),
                "provable": False,
            }

        # Gate 2: CONSUMPTION — must be first and only consumption
        # Qwen R2 F-NEW-01: consumption_result=None is NOT safe to skip
        # A DB failure returning None must be treated as NOT_PROVABLE → REFUSED
        # Qwen R2 F-NEW-02: must use strict bool check, not truthiness
        # consumed="False" (string) is truthy in Python — must compare to True explicitly
        if consumption_result is None:
            return {
                "release": "REFUSED",
                "gate_failed": "CONSUMPTION_MISSING",
                "primary_code": "CONSUMPTION_LOCK_FAILED",
                "state_mutation": "NONE",
                "vcb_inv": "INV-COMMIT-02",
                "reason": "NOT_PROVABLE.CONSUMPTION_RESULT_ABSENT — DB failure or missing check",
                "provable": False,
                "fail_closed": True,
            }
        # Strict bool comparison — rejects strings, 0, None, empty dict
        consumed_value = consumption_result.get("consumed")
        if consumed_value is not True:
            return {
                "release": "REFUSED",
                "gate_failed": "CONSUMPTION",
                "primary_code": "CONSUMPTION_ALREADY_USED",
                "state_mutation": "NONE",
                "vcb_inv": "INV-COMMIT-02",
                "reason": consumption_result.get("reason", "ALREADY_CONSUMED"),
                "provable": False,
                "replay_detected": consumed_value is False,
                "type_error_detected": not isinstance(consumed_value, bool),
            }

        # Gate 3: STILL — P3.2 internal query (no longer caller-supplied bypass risk)
        still_status = "NOT_ENFORCED_SPEC_ONLY"
        still_examination = None

        if enforce_still and not authority_id:
            # ADR-011: enforce_still=True without authority_id is a bypass attempt
            # Cannot perform live STILL check without knowing which mandate to check
            # Must refuse rather than silently pass — closing the caller-supplied bypass
            return build_rejection_result(
                gate_failed="STILL",
                code="STILL_CANNOT_VERIFY",
                message=(
                    "enforce_still=True requires authority_id to perform live STILL check. "
                    "Refusing rather than proceeding without verification. (ADR-011)"
                ),
            )

        if authority_id and enforce_still:
            # STILL queried INTERNALLY via sync in-memory check (INV-AUTH-TEMP-01)
            # Caller cannot bypass by injecting still_result='PROVABLE'
            # Sync path: directly query _TREASURY_MANDATES without async overhead
            # Production upgrade: replace with Supabase SELECT FOR UPDATE
            try:
                mandate = _TREASURY_MANDATES.get(authority_id)
                if mandate is None:
                    _sync_still_result = "NOT_PROVABLE"
                    _sync_still_failures = ["NOT_PROVABLE.NO_MANDATE_EXISTS"]
                elif mandate.get("status") in ("REVOKED", "EXPIRED", "SUSPENDED"):
                    _sync_still_result = "FAILED"
                    _sync_still_failures = [f"STILL_FAILED.AUTHORITY_{mandate.get('status')}"]
                else:
                    # Scope check
                    scope_ok = True
                    scope_failures = []
                    if proposed_amount is not None:
                        if proposed_amount > mandate.get("amount_limit", 0):
                            scope_ok = False
                            scope_failures.append(
                                f"SCOPE_EXCEEDED: {proposed_amount} > {mandate.get('amount_limit')}")
                    if proposed_vendor is not None:
                        if proposed_vendor not in mandate.get("authorized_vendors", []):
                            scope_ok = False
                            scope_failures.append(f"VENDOR_NOT_AUTHORIZED: {proposed_vendor}")
                    if scope_ok:
                        _sync_still_result = "PROVABLE"
                        _sync_still_failures = []
                    else:
                        _sync_still_result = "FAILED"
                        _sync_still_failures = scope_failures

                if _sync_still_result != "PROVABLE":
                    still_examination = type("_SR", (), {
                        "result": _sync_still_result,
                        "node_id": f"STILL-SYNC-{authority_id[:16]}",
                        "authority_status": mandate.get("status","UNKNOWN") if mandate else "NOT_FOUND",
                        "delta_classification": "MATERIAL_DELTA" if _sync_still_result=="FAILED" else "UNKNOWN_DELTA",
                        "failure_reasons": _sync_still_failures,
                    })()
                    still_status = _sync_still_result
                else:
                    still_examination = None
                    still_status = "PROVABLE"

                if still_examination and _sync_still_result != "PROVABLE":
                        return {
                            "release": "REFUSED",
                            "gate_failed": "STILL",
                            "primary_code": "STILL_AUTHORITY_REVOKED",
                            "state_mutation": "NONE",
                            "vcb_inv": "INV-COMMIT-02",
                            "reason": f"Authority continuity: {still_examination.result}",
                            "failure_reasons": still_examination.failure_reasons,
                            "provable": False,
                            "still_examination": {
                                "result": still_examination.result,
                                "node_id": still_examination.node_id,
                                "authority_status": still_examination.authority_status,
                                "delta": still_examination.delta_classification,
                            }
                        }
            except Exception as e:
                # Fail closed — STILL query failure → NOT_PROVABLE → refuse
                return {
                    "release": "REFUSED",
                    "gate_failed": "STILL_QUERY_EXCEPTION",
                "primary_code": "STILL_SOURCE_UNAVAILABLE",
                "state_mutation": "NONE",
                "vcb_inv": "INV-COMMIT-02",
                    "reason": f"NOT_PROVABLE.STILL_QUERY_FAILED: {str(e)[:80]}",
                    "provable": False,
                    "fail_closed": True,
                }
        elif still_result not in ("NOT_VERIFIED", "NOT_ENFORCED"):
            # Document v2.2 F-2.2-05: positive allowlist — only known safe states pass
            # Unknown values must refuse, not silently pass
            STILL_ADMISSIBLE = frozenset({"PROVABLE", "GOOD"})
            STILL_REFUSED = frozenset({"FAILED", "RE_ENTRY_REQUIRED", "NOT_PROVABLE"})
            if still_result in STILL_REFUSED:
                return {
                    "release": "REFUSED",
                    "gate_failed": "STILL",
                    "primary_code": "STILL_AUTHORITY_REVOKED",
                    "state_mutation": "NONE",
                    "vcb_inv": "INV-COMMIT-02",
                    "reason": f"Authority continuity: {still_result}",
                    "provable": False,
                }
            elif still_result not in STILL_ADMISSIBLE:
                # Unknown value — fail closed per INV-STILL-01
                return {
                    "release": "REFUSED",
                    "gate_failed": "STILL_UNKNOWN_VALUE",
                "primary_code": "STILL_UNKNOWN_STATUS",
                "state_mutation": "NONE",
                "vcb_inv": "INV-COMMIT-02",
                    "reason": f"NOT_PROVABLE.STILL_UNKNOWN: {repr(still_result)} not in admissible set",
                    "admissible": list(STILL_ADMISSIBLE),
                    "provable": False,
                    "fail_closed": True,
                }
            still_status = still_result

        # Gate 4: COULD — SPEC_ONLY, logged but not yet blocking
        # Document v2.2 F-2.2-05: unknown values must refuse, not silently pass
        could_status = "NOT_ENFORCED_SPEC_ONLY"
        if could_result not in ("NOT_VERIFIED", "NOT_ENFORCED"):
            COULD_ADMISSIBLE = frozenset({"PROVABLE", "LEVERAGE_PRESENT", "ACTUAL_CAUSE"})
            COULD_REFUSED = frozenset({"LEVERAGE_LOST", "NOT_PROVABLE", "NOT_ACTUAL_CAUSE", "NOT_MODELLED"})
            if could_result in COULD_REFUSED:
                return {
                    "release": "REFUSED",
                    "gate_failed": "COULD",
                    "primary_code": "COULD_NO_LEVERAGE",
                    "state_mutation": "NONE",
                    "vcb_inv": "INV-COMMIT-02",
                    "reason": f"Boundary leverage: {could_result}",
                    "provable": False,
                }
            elif could_result not in COULD_ADMISSIBLE:
                # Unknown value — fail closed
                return {
                    "release": "REFUSED",
                    "gate_failed": "COULD_UNKNOWN_VALUE",
                "primary_code": "COULD_NO_LEVERAGE",
                "state_mutation": "NONE",
                "vcb_inv": "INV-COMMIT-02",
                    "reason": f"NOT_PROVABLE.COULD_UNKNOWN: {repr(could_result)} not in admissible set",
                    "admissible": list(COULD_ADMISSIBLE),
                    "provable": False,
                    "fail_closed": True,
                }
            could_status = could_result

        # All gates passed
        return {
            # NOTE: EXAMINATION_PARTIAL_PASS not RELEASE_GRANTED
            # ChatGPT R2 NEW-F16: "RELEASE_GRANTED implies full INV-01 enforcement"
            # P4: RELEASE_GRANTED — all enforced gates pass
            # STILL and COULD limitations documented below — not yet full enforcement
            # The mock actuator gates on this value (P4 invariant proof)
            "release": "RELEASE_GRANTED",
            "why": "PROVABLE",
            "still": still_status,
            "could": could_status,
            "consumption": "CONSUMED",
            "note": "WHY and CONSUMPTION enforced. STILL/COULD documented as scope limits.",
            "claim_limitations": [
                "STILL not enforced at gate (R003 SPEC_ONLY) — authority continuity unverified",
                "COULD not enforced at gate (no real actuator) — boundary leverage unverified",
                "This is a PARTIAL examination result, not a full INV-01 release authorization",
            ],
            "provable": "PARTIAL",
        }

    except Exception as e:
        # FAIL CLOSED — any exception → NOT_PROVABLE → refuse
        # Never silently convert an exception to ALLOW
        return {
            "release": "REFUSED",
            "gate_failed": "EVALUATE_RELEASE_EXCEPTION",
                "primary_code": "GATE_UNDETERMINED",
                "state_mutation": "NONE",
                "vcb_inv": "INV-COMMIT-02",
            "reason": f"NOT_PROVABLE.GATE_EXCEPTION: {str(e)[:100]}",
            "provable": False,
            "fail_closed": True,
            "note": "Exception in evaluate_release() always produces REFUSED — fail-closed confirmed",
        }


# ─────────────────────────────────────────────────────────────────────────────
# DECLARATION OBLIGATION — Expert-approved addition
# Evidenced Silence: when required accountability does not occur,
# the absence becomes a positively evidenced, cryptographically timestamped event.
# This is VCB's strongest differentiator vs enforcement gateways (AGT, AgentLock):
# they gate before execution. VCB evidences what happened at execution —
# including when required human accountability never responded.
# ─────────────────────────────────────────────────────────────────────────────

from pydantic import BaseModel
class DeclarationObligationRequest(BaseModel):
    """Open a Declaration Obligation when a materiality threshold is crossed."""
    obligation_id: Optional[str] = None
    originating_event_hash: str          # hash of the triggering evidence event
    affected_scope: str                  # what consequential action/decision is affected
    responsible_identity: str            # cryptographically identified accountable party
    responsible_role: str                # CFO, DPO, system owner, etc.
    materiality_rule: str               # which rule triggered this obligation
    basis_evidence: dict                # the evidence that triggered the threshold
    deadline_hours: int = 72            # default 72-hour window
    escalation_identity: Optional[str] = None  # who to escalate to on DECLARATION_SILENT


@app.post("/v1/declaration/open", tags=["Declaration Obligation"])
async def open_declaration_obligation(
    req: DeclarationObligationRequest,
    x_api_key: str = Header(None, alias="X-API-Key"),
    authorization: str = Header(None),
):
    """
    Open a Declaration Obligation when a materiality threshold is crossed.

    Expert direction: VCB does not claim it can force accountability.
    It proves when accountability was required, who was responsible,
    what deadline existed, and whether a response occurred.

    This is the DECLARATION OBLIGATION mechanism.
    If no valid declaration is received before deadline: DECLARATION_SILENT.
    DECLARATION_SILENT is a positively evidenced event, not an absence.
    """
    require_api_key(x_api_key, authorization)
    ts = datetime.now(timezone.utc).isoformat()
    obligation_id = req.obligation_id or f"OBL-{_vcc_hash({'ts':ts,'scope':req.affected_scope})[:16].upper()}"
    deadline_at = (datetime.now(timezone.utc) + __import__('datetime').timedelta(hours=req.deadline_hours)).isoformat()

    # Build obligation record — cryptographically bound
    obligation = {
        "schema": "VGS-DECLARATION-OBLIGATION-1.0",
        "obligation_id": obligation_id,
        "status": "OPEN",
        "opened_at": ts,
        "deadline_at": deadline_at,
        "deadline_hours": req.deadline_hours,
        "originating_event_hash": req.originating_event_hash,
        "affected_scope": req.affected_scope,
        "responsible_identity": req.responsible_identity,
        "responsible_role": req.responsible_role,
        "materiality_rule": req.materiality_rule,
        "basis_evidence_hash": _vcc_hash(req.basis_evidence),
        "escalation_identity": req.escalation_identity,
        "declaration_received": False,
        "declaration_silent_at": None,
        "vcb_principle": "VCB does not force accountability. It evidences whether it occurred.",
    }

    # Sign the obligation
    obligation["integrity_hash"] = _vcc_hash(obligation)
    obligation["signature"] = sign_payload(obligation)

    # Store in registry
    _DECLARATION_REGISTRY[obligation_id] = obligation

    return {
        "obligation_id": obligation_id,
        "status": "OPEN",
        "deadline_at": deadline_at,
        "responsible_identity": req.responsible_identity,
        "message": f"Declaration obligation opened. Response required by {deadline_at}.",
        "declaration_endpoint": f"POST /v1/declaration/{obligation_id}/respond",
        "silence_endpoint": f"GET /v1/declaration/{obligation_id}/status",
    }


@app.post("/v1/declaration/{obligation_id}/respond", tags=["Declaration Obligation"])
async def respond_to_declaration(
    obligation_id: str,
    x_api_key: str = Header(None, alias="X-API-Key"),
    authorization: str = Header(None),
    disposition: str = "RELIANCE_REAFFIRMED",  # or NON_RELIANCE_DECLARED
    basis: Optional[str] = None,
    responder_identity: Optional[str] = None,
):
    """
    Record a declaration response — RELIANCE_REAFFIRMED or NON_RELIANCE_DECLARED.
    The response itself is cryptographically signed and timestamped.
    """
    require_api_key(x_api_key, authorization)
    ts = datetime.now(timezone.utc).isoformat()

    if obligation_id not in _DECLARATION_REGISTRY:
        return {"error": "OBLIGATION_NOT_FOUND", "obligation_id": obligation_id}

    obl = _DECLARATION_REGISTRY[obligation_id]

    if obl["status"] == "DECLARATION_SILENT":
        return {"error": "OBLIGATION_CLOSED_SILENT", "closed_at": obl.get("declaration_silent_at")}

    if disposition not in ("RELIANCE_REAFFIRMED", "NON_RELIANCE_DECLARED"):
        return {"error": "INVALID_DISPOSITION", "valid": ["RELIANCE_REAFFIRMED", "NON_RELIANCE_DECLARED"]}

    response_record = {
        "schema": "VGS-DECLARATION-RESPONSE-1.0",
        "obligation_id": obligation_id,
        "disposition": disposition,
        "responded_at": ts,
        "responder_identity": responder_identity or obl.get("responsible_identity"),
        "basis": basis or "No basis provided",
        "within_deadline": ts <= obl["deadline_at"],
    }
    response_record["integrity_hash"] = _vcc_hash(response_record)
    response_record["signature"] = sign_payload(response_record)

    obl["status"] = disposition
    obl["declaration_received"] = True
    obl["response"] = response_record

    return {
        "obligation_id": obligation_id,
        "status": disposition,
        "responded_at": ts,
        "within_deadline": response_record["within_deadline"],
        "cryptographic_record": response_record["integrity_hash"],
    }


@app.get("/v1/declaration/{obligation_id}/status", tags=["Declaration Obligation"])
async def get_declaration_status(
    obligation_id: str,
    x_api_key: str = Header(None, alias="X-API-Key"),
    authorization: str = Header(None),
):
    """
    Check obligation status. If deadline passed without response: records DECLARATION_SILENT.
    DECLARATION_SILENT is not a system failure — it is positively evidenced accountability absence.
    This is VCB's 'Evidenced Silence' mechanism.
    """
    require_api_key(x_api_key, authorization)
    ts = datetime.now(timezone.utc).isoformat()

    if obligation_id not in _DECLARATION_REGISTRY:
        return {"error": "OBLIGATION_NOT_FOUND"}

    obl = _DECLARATION_REGISTRY[obligation_id]

    # Check if deadline passed without response
    if (obl["status"] == "OPEN" and
        ts > obl["deadline_at"] and
        not obl["declaration_received"]):

        # Record DECLARATION_SILENT — positively evidenced
        silence_record = {
            "schema": "VGS-DECLARATION-SILENT-1.0",
            "obligation_id": obligation_id,
            "event": "DECLARATION_SILENT",
            "silent_at": ts,
            "deadline_was": obl["deadline_at"],
            "responsible_identity": obl["responsible_identity"],
            "responsible_role": obl["responsible_role"],
            "affected_scope": obl["affected_scope"],
            "vcb_statement": (
                "The obligation existed. The responsible party was identified. "
                "The deadline elapsed. No valid declaration was recorded. "
                "This absence is itself a positively evidenced governance event."
            ),
        }
        silence_record["integrity_hash"] = _vcc_hash(silence_record)
        silence_record["signature"] = sign_payload(silence_record)

        obl["status"] = "DECLARATION_SILENT"
        obl["declaration_silent_at"] = ts
        obl["silence_record"] = silence_record

    return {
        "obligation_id": obligation_id,
        "status": obl["status"],
        "opened_at": obl["opened_at"],
        "deadline_at": obl["deadline_at"],
        "responsible_identity": obl["responsible_identity"],
        "declaration_received": obl["declaration_received"],
        "declaration_silent_at": obl.get("declaration_silent_at"),
        "provable": obl["status"] != "OPEN",
        "evidence_type": "DECLARATION_SILENT" if obl["status"] == "DECLARATION_SILENT" else obl["status"],
    }


