# ── SUPABASE DDL (V-001 production schema) ───────────────────

SUPABASE_DDL = """
-- VeriSigilAI Production Persistence Schema
-- Run once in Supabase SQL editor before multi-instance deployment

CREATE TABLE IF NOT EXISTS vcb_sigilmarks (
    sigilmark_id    TEXT PRIMARY KEY,
    status          TEXT NOT NULL DEFAULT 'NOT_YET_CONSUMED'
                    CHECK (status IN ('NOT_YET_CONSUMED','CONSUMED','INVALID','EXPIRED')),
    payload         JSONB NOT NULL,
    issued_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    consumed_at     TIMESTAMPTZ,
    consumed_by     TEXT,          -- instance ID that consumed
    expires_at      TIMESTAMPTZ NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_sigilmarks_id ON vcb_sigilmarks(sigilmark_id);

CREATE TABLE IF NOT EXISTS vcb_proof_records (
    proof_id        TEXT PRIMARY KEY,
    proof_type      TEXT NOT NULL,  -- 'GCP','AR','CONTINUITY','CEE','CBA'
    payload         JSONB NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS vcb_ledger (
    tx_id           TEXT PRIMARY KEY,
    sigilmark_id    TEXT REFERENCES vcb_sigilmarks(sigilmark_id),
    action          JSONB NOT NULL,
    consequence     TEXT NOT NULL,
    committed_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- CRITICAL: The atomic consumption function
-- This is what replaces threading.Lock() for distributed safety
CREATE OR REPLACE FUNCTION consume_sigilmark(p_id TEXT, p_instance TEXT)
RETURNS TABLE(consumed BOOLEAN, reason TEXT) AS $$
BEGIN
    UPDATE vcb_sigilmarks
    SET status = 'CONSUMED', consumed_at = NOW(), consumed_by = p_instance
    WHERE sigilmark_id = p_id
    AND   status = 'NOT_YET_CONSUMED'
    AND   expires_at > NOW();
    IF FOUND THEN
        RETURN QUERY SELECT TRUE, 'CONSUMED'::TEXT;
    ELSE
        RETURN QUERY SELECT FALSE,
            CASE
                WHEN EXISTS(SELECT 1 FROM vcb_sigilmarks WHERE sigilmark_id=p_id AND status='CONSUMED')
                THEN 'ALREADY_CONSUMED'
                WHEN EXISTS(SELECT 1 FROM vcb_sigilmarks WHERE sigilmark_id=p_id AND expires_at<=NOW())
                THEN 'EXPIRED'
                ELSE 'NOT_FOUND'
            END::TEXT;
    END IF;
END;
$$ LANGUAGE plpgsql;
"""

SUPABASE_PERSISTENCE_SPEC = {
    "schema":  "VGS-SUPABASE-PERSISTENCE-SPEC-1.0",
    "purpose": "V-001 fix: governance state must survive process termination, restart, deployment replacement",
    "tables":  ["vcb_sigilmarks","vcb_proof_records","vcb_ledger"],
    "critical_function": "consume_sigilmark(id, instance) — atomic UPDATE WHERE status='NOT_YET_CONSUMED'",
    "invariant": "ONE SigilMark → AT MOST ONE successful consumption, durable across restarts and instances",
    "ddl":     SUPABASE_DDL,
    "test_before_deploy": [
        "Issue SigilMark → verify in DB",
        "Consume → verify status='CONSUMED' in DB",
        "Restart server → consumed state loaded from DB, NOT from memory",
        "Replay same SigilMark → ALREADY_CONSUMED",
        "Two instances simultaneous → exactly 1 CONSUMED row, rowcount=1 constraint",
    ],
}


async def _supabase_consume_sigilmark(sigilmark_id: str) -> dict:
    """
    V-001/V-002 fix: atomic Supabase consumption.
    Replaces threading.Lock() for distributed safety.

    Returns: {consumed: bool, reason: str}
    consumed=True: first and only consumption
    consumed=False + ALREADY_CONSUMED: replay attempt — REJECT
    consumed=False + EXPIRED: TTL exceeded — REJECT
    consumed=False + NOT_FOUND: unregistered — REJECT
    """
    import os
    supabase_url = os.environ.get("SUPABASE_URL","")
    supabase_key = os.environ.get("SUPABASE_KEY","")

    if not supabase_url or not supabase_key or "placeholder" in supabase_url:
        # IN_MEMORY_FALLBACK — documented blocker
        # Do NOT weaken the invariant. Fall back to in-memory for dev only.
        with _VCC_LOCK:
            if sigilmark_id in _VCC_CONSUMED:
                return {"consumed": False, "reason": "ALREADY_CONSUMED",
                        "mechanism": "IN_MEMORY_FALLBACK",
                        "WARNING": "V-001 not fixed — configure Supabase for production"}
            _VCC_CONSUMED.add(sigilmark_id)
            sm = _SIGILMARK_REGISTRY.get(sigilmark_id,{})
            if sm: sm["status"] = "CONSUMED"
            return {"consumed": True, "reason": "CONSUMED",
                    "mechanism": "IN_MEMORY_FALLBACK",
                    "WARNING": "V-001 not fixed — state lost on restart"}

    # Production path: atomic Supabase RPC
    # REQUIRED SQL in Supabase consume_sigilmark function (verify in dashboard):
    #   CREATE OR REPLACE FUNCTION consume_sigilmark(p_id text, p_instance text)
    #   RETURNS TABLE(sigilmark_id text, consumed boolean, reason text) AS $$
    #   BEGIN
    #     -- Gemini R2 REG-F01: PostgREST defaults to READ COMMITTED isolation.
    #     -- Must explicitly set SERIALIZABLE to prevent concurrent dual-consumption.
    #     SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
    #
    #     UPDATE vcb_sigilmarks
    #     SET status='CONSUMED', consumed_at=NOW(), consumed_by=p_instance
    #     WHERE vcb_sigilmarks.sigilmark_id=p_id AND status='NOT_YET_CONSUMED';
    #
    #     IF FOUND THEN
    #       RETURN QUERY SELECT p_id, true, 'CONSUMED';
    #     ELSE
    #       RETURN QUERY SELECT p_id, false, 'ALREADY_CONSUMED';
    #     END IF;
    #   END;
    #   $$ LANGUAGE plpgsql;
    #
    #   -- Gemini R2 NEW-04: DB-level monotonicity trigger (verify in dashboard):
    #   -- CREATE OR REPLACE FUNCTION prevent_consumption_reversal()
    #   -- RETURNS TRIGGER AS $$
    #   -- BEGIN
    #   --   IF OLD.status = 'CONSUMED' AND NEW.status != 'CONSUMED' THEN
    #   --     RAISE EXCEPTION 'Cannot reverse CONSUMED state for %', OLD.sigilmark_id;
    #   --   END IF;
    #   --   RETURN NEW;
    #   -- END;
    #   -- $$ LANGUAGE plpgsql;
    #   --
    #   -- CREATE TRIGGER enforce_consumption_monotonicity
    #   -- BEFORE UPDATE ON vcb_sigilmarks
    #   -- FOR EACH ROW EXECUTE FUNCTION prevent_consumption_reversal();
    #
    # VERIFY BOTH in Supabase SQL editor before claiming distributed atomicity.
    try:
        import httpx
        instance_id = os.environ.get("RAILWAY_REPLICA_ID", "instance-0")
        async with httpx.AsyncClient() as client:
            resp = await client.post(
                f"{supabase_url}/rest/v1/rpc/consume_sigilmark",
                headers={"apikey": supabase_key, "Authorization": f"Bearer {supabase_key}",
                         "Content-Type": "application/json"},
                json={"p_id": sigilmark_id, "p_instance": instance_id},
                timeout=5.0,
            )
            data = resp.json()
            if isinstance(data, list) and data:
                row = data[0]
                return {
                    "consumed":  row.get("consumed", False),
                    "reason":    row.get("reason","UNKNOWN"),
                    "mechanism": "SUPABASE_ATOMIC_RPC",
                    "instance":  instance_id,
                }
            return {"consumed": False, "reason": "RPC_ERROR", "mechanism": "SUPABASE_ATOMIC_RPC", "raw": str(data)}
    except Exception as e:
        # Fail closed — do not grant consumption on DB error
        return {"consumed": False, "reason": f"DB_ERROR_FAIL_CLOSED: {str(e)[:60]}",
                "mechanism": "SUPABASE_ATOMIC_RPC", "fail_closed": True}


async def _supabase_restore_consumed_state():
    """
    V-001 fix: on startup, restore consumed SigilMark IDs from Supabase.
    Prevents restart-replay attacks.
    Called at application startup.
    """
    import os
    supabase_url = os.environ.get("SUPABASE_URL","")
    supabase_key = os.environ.get("SUPABASE_KEY","")
    if not supabase_url or not supabase_key or "placeholder" in supabase_url:
        return {
            "restored": 0,
            "mechanism": "IN_MEMORY_FALLBACK",
            "WARNING": "V-001 not fixed — consumed state NOT restored on restart. Replay possible.",
        }
    try:
        import httpx
        async with httpx.AsyncClient() as client:
            resp = await client.get(
                f"{supabase_url}/rest/v1/vcb_sigilmarks?status=eq.CONSUMED&select=sigilmark_id",
                headers={"apikey": supabase_key, "Authorization": f"Bearer {supabase_key}"},
                timeout=10.0,
            )
            rows = resp.json()
            if isinstance(rows, list):
                with _VCC_LOCK:
                    for row in rows:
                        sid = row.get("sigilmark_id","")
                        if sid:
                            _VCC_CONSUMED.add(sid)
                            if sid in _SIGILMARK_REGISTRY:
                                _SIGILMARK_REGISTRY[sid]["status"] = "CONSUMED"
                return {"restored": len(rows), "mechanism": "SUPABASE_RESTORE"}
            return {"restored": 0, "mechanism": "SUPABASE_RESTORE", "error": str(rows)}
    except Exception as e:
        return {"restored": 0, "mechanism": "SUPABASE_RESTORE",
                "error": f"RESTORE_FAILED_FAIL_CLOSED: {str(e)[:60]}"}


# ── TEST A: RESTART REPLAY ────────────────────────────────────

@app.post("/v1/adversarial/restart-replay", tags=["Adversarial Proof Gates"])
async def adversarial_restart_replay(
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    P0-04/P0-07 — Restart Replay Test (V-001 live proof).
    Expert requirement: all 12 evidence fields must be present in response.

    Sequence:
      1. Issue VCC (SigilMark)
      2. Verify/consume it (first use — should PASS)
      3. Simulate restart — clear in-memory state
      4. Replay same VCC (should FAIL if DB is authoritative)

    If Supabase is configured: consumed state persists → replay FAILS → PASS
    If Supabase not available: replay SUCCEEDS → V-001-UNRESOLVED

    Evidence fields per expert requirement:
      test_id, build_hash, database_target, initial_state, consume_result,
      persistence_result, restart_event, post_restart_state, replay_result,
      expected_result, actual_result, environment, timestamp
    """
    require_api_key(x_api_key, authorization)

    import os
    build = _get_full_build_identity()
    ts    = datetime.now(timezone.utc).isoformat()
    action = {"type": "refund", "amount": 100000, "beneficiary": "AGENT-TEST", "currency": "NGN"}

    supabase_url = os.environ.get("SUPABASE_URL", "")
    has_db = bool(supabase_url) and "placeholder" not in supabase_url and supabase_url != "https://x.supabase.co"
    database_target = supabase_url[:40] + "..." if has_db else "IN_MEMORY_ONLY"
    environment = "PRODUCTION_SUPABASE" if has_db else "IN_MEMORY_FALLBACK"

    # Step 1: Issue VCC
    try:
        vcc = issue_vcc_safe(
            vcb_decision_id   = f"TEST-RESTART-{ts}",
            action_payload    = action,
            consequence_type  = "TEST_REFUND",
            material_bounds   = {"max_amount": 500000, "currency": "NGN"},
            authority_hash    = _vcc_hash({"auth": "test-authority"}),
            policy_hash       = _vcc_hash({"policy": "test-v1"}),
            state_hash        = _vcc_hash({"state": "active"}),
            enforcement_point = "test-actuator",
            ttl_seconds       = 300,
        )
        vcc_id     = vcc.get("vcc_id", "UNKNOWN")
        issue_ok   = True
        initial_state = {"vcc_id": vcc_id, "status": "NOT_YET_CONSUMED", "in_memory": True, "db": has_db}
    except Exception as e:
        return {
            "schema": "VGS-TEST-A-RESTART-REPLAY-1.0",
            "test_id": "P0-04-RESTART-REPLAY",
            "build_hash": build["sha256_full"][:32],
            "database_target": database_target,
            "error": f"VCC issue failed: {type(e).__name__}: {e}",
            "verdict": "NOT_PROVABLE",
            "timestamp": ts,
        }

    # Step 2: First verification (consume)
    try:
        r1 = verify_vcc_independent(vcc, presented_action=action, presented_enforcement_point="test-actuator")
        first_result  = r1.get("result", "UNKNOWN")
        consume_result = "CONSUMED" if first_result == "VALID" else f"UNEXPECTED: {first_result}"
    except Exception as e:
        consume_result = f"ERROR: {e}"
        first_result   = "ERROR"

    # Step 3: Simulate restart — clear in-memory state only
    with _VCC_LOCK:
        _VCC_CONSUMED.discard(vcc_id)
        if vcc_id in _VCC_REGISTRY:
            _VCC_REGISTRY[vcc_id]["status"] = "NOT_YET_CONSUMED"
    restart_event    = "IN_MEMORY_STATE_CLEARED — simulates process restart"

    # Step 3b: Restore consumed state from Supabase (as real restart would do)
    db_restore_result = "SKIPPED_NO_DB"
    if has_db:
        try:
            restore = await _supabase_restore_consumed_state()
            db_restore_result = f"RESTORED_{restore.get('restored', 0)}_RECORDS"
        except Exception as e:
            db_restore_result = f"RESTORE_ERROR: {e}"

    post_restart_state = {
        "in_memory_cleared": True,
        "db_restore_attempted": has_db,
        "db_restore_result": db_restore_result,
        "db_state": "CONSUMED (persists in Supabase)" if has_db else "NOT_YET_CONSUMED (no DB)",
    }

    # Step 4: Replay after simulated restart
    # Now use _supabase_consume_sigilmark for the replay check
    # This checks the DB directly, not just in-memory
    try:
        if has_db:
            # Use the production path: attempt DB consumption
            replay_db = await _supabase_consume_sigilmark(vcc_id)
            replay_blocked_by_db = not replay_db.get("consumed", True)
            replay_result  = "ALREADY_CONSUMED" if replay_blocked_by_db else "CONSUMED_AGAIN"
            actual_result  = "REPLAY_BLOCKED" if replay_blocked_by_db else "REPLAY_SUCCEEDED"
        else:
            # No DB: use in-memory verify
            r2 = verify_vcc_independent(vcc, presented_action=action, presented_enforcement_point="test-actuator")
            replay_result  = r2.get("result", "UNKNOWN")
            actual_result  = "REPLAY_BLOCKED" if replay_result != "VALID" else "REPLAY_SUCCEEDED"
    except Exception as e:
        replay_result = f"ERROR: {e}"
        actual_result = "ERROR"

    # Verdict
    expected_result = "REPLAY_BLOCKED" if has_db else "REPLAY_SUCCEEDED_V001_UNRESOLVED"
    replay_blocked  = actual_result == "REPLAY_BLOCKED"

    if has_db and replay_blocked:
        verdict    = "PASS"
        persistence_result = "SUPABASE_AUTHORITATIVE — consumed state survived simulated restart"
        v001_state = "D_RESTART_SINGLE_INSTANCE_TESTED"
    elif has_db and not replay_blocked:
        verdict    = "FAIL — DB configured but replay succeeded. Check Supabase DDL."
        persistence_result = "DB_DID_NOT_PREVENT_REPLAY"
        v001_state = "D_RESTART_SINGLE_INSTANCE_TESTED"
    else:
        verdict    = "V-001-UNRESOLVED"
        persistence_result = "IN_MEMORY_FALLBACK — run Supabase DDL and configure env vars"
        v001_state = "D_RESTART_SINGLE_INSTANCE_TESTED"

    return {
        "schema":             "VGS-TEST-A-RESTART-REPLAY-1.0",
        "test_id":            "P0-04-RESTART-REPLAY",
        "build_hash":         build["sha256_full"][:32],
        "database_target":    database_target,
        "environment":        environment,
        "initial_state":      initial_state,
        "consume_result":     consume_result,
        "step_1_first_use":   first_result,
        "persistence_result": persistence_result,
        "restart_event":      restart_event,
        "post_restart_state": post_restart_state,
        "replay_result":      replay_result,
        "expected_result":    expected_result,
        "actual_result":      actual_result,
        "verdict":            verdict,
        "v001_maturity":      v001_state,
        "expert_note":        "A PASS response without execution evidence is itself a failed VCB test.",
        "next_step":          "POST /v1/adversarial/distributed-atomicity for V-002" if verdict == "PASS" else "Run Supabase DDL then redeploy Railway",
        "timestamp":          ts,
    }


@app.post("/v1/adversarial/distributed-replay", tags=["Adversarial Proof Gates"])
async def adversarial_distributed_replay(
    req: dict,
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
):
    """
    Test B + C: Distributed replay and crash boundary tests.
    Returns current spec and status.
    Full execution requires Supabase + multiple Railway instances.
    """
    require_api_key(x_api_key, authorization)
    import os
    has_db = bool(os.environ.get("SUPABASE_URL","")) and "placeholder" not in os.environ.get("SUPABASE_URL","")
    ts = datetime.now(timezone.utc).isoformat()

    # Single-instance simulation (100 threads — already passing)
    action   = req.get("action") or {"type":"test","amount":1000,"beneficiary":"A"}
    vcb_dec  = build_vcb_decision_object(
        decision="ALLOW", action_hash=_vcc_hash(action), consequence_type="TEST",
        authority_hash=_vcc_hash({"a":"t"}), policy_hash=_vcc_hash({"p":"1"}),
        state_hash=_vcc_hash({"s":"1"}), enforcement_path="test",
    )
    sm = issue_sigilmark(vcb_decision=vcb_dec, action_payload=action,
                         enforcement_point="test", ttl_seconds=300)

    import threading
    results, lock = [], threading.Lock()
    def try_consume():
        r = verify_sigilmark_independent(sm, presented_action=action, presented_enforcement_point="test")
        with lock: results.append(r["result"])
    threads = [threading.Thread(target=try_consume) for _ in range(50)]
    for t in threads: t.start()
    for t in threads: t.join()
    valid_count = results.count("VALID")

    return {
        "schema":              "VGS-DISTRIBUTED-REPLAY-1.0",
        "test_B_spec":         TWO_PROCESS_RACE_SPEC,
        "test_C_spec":         CRASH_BOUNDARY_SPEC,
        "single_instance_test": {
            "threads":         50,
            "valid_count":     valid_count,
            "status":          "PASS" if valid_count == 1 else "FAIL",
            "note":            "threading.Lock — single process only",
        },
        "multi_instance_status": "PENDING — requires Supabase + 2 Railway instances",
        "has_supabase":        has_db,
        "V001_fix_required":   not has_db,
        "V002_fix_required":   not has_db,
        "supabase_ddl":        "GET /v1/engineering/supabase-ddl",
        "production_acceptance_test": "Both Test B and Test C must PASS before production designation",
        "timestamp":           ts,
    }


