        examination_result={"verdict":"ADMISSIBLE"},
        consumption_result={"consumed":True},
        authority_id="MANDATE-FP-REPORT",
        t0_baseline_hash="fp-test",
        proposed_amount=5000.0,
        proposed_vendor="VENDOR-A",
        enforce_still=True,
